window.ASTROKDOK_DESAFIOS = [{"m":1,"missao":"TERRA","materia":"PORTUGUÊS","aula":"Ler como detetive","p":"Leia: \"A Lua não tem luz própria. Ela brilha porque reflete a luz do Sol, como um espelho.\" Qual é o TEMA do texto?","dica":"O tema é o assunto. Pergunte: de que o texto fala do começo ao fim?","porque":"As duas frases falam de por que a Lua brilha. O espelho só aparece numa comparação: ele não é o assunto.","tipo":"opcoes","o":["Os espelhos","O brilho da Lua","As estrelas","A noite"],"a":1},{"m":1,"missao":"TERRA","materia":"PORTUGUÊS","aula":"Ler como detetive","p":"Qual é a finalidade de uma receita de bolo?","dica":"Pense no que você faz com uma receita: lê e depois... faz o quê?","porque":"A receita mostra os ingredientes e os passos para quem quer fazer o bolo. A finalidade dela é ensinar.","tipo":"opcoes","o":["Contar uma história","Convencer a comprar um bolo","Divertir com uma piada","Ensinar a fazer o bolo"],"a":3},{"m":1,"missao":"TERRA","materia":"PORTUGUÊS","aula":"Ler como detetive","p":"Leia: \"O Calhambeque-1 é feito de caixa-d'água velha e fita adesiva. Muita gente ri dele. Mas ele já subiu três vezes e voltou inteiro.\" Qual é a ideia principal?","dica":"Procure a palavra que muda o rumo do texto. Depois do \"mas\" costuma vir o mais importante.","porque":"O texto mostra o lado ruim (feia, gente rindo) e, depois do \"mas\", o que importa: a nave voa e volta inteira.","tipo":"opcoes","o":["A nave é feia, mas funciona","Fita adesiva é cara","Ninguém gosta da nave","A nave nunca voou"],"a":0},{"m":1,"missao":"TERRA","materia":"PORTUGUÊS","aula":"Ler como detetive","p":"Leia: \"Quando cadete chegou à escola, o pátio estava cheio de poças e todos fechavam os guarda-chuvas.\" O que dá para concluir, mesmo sem estar escrito?","dica":"Junte as pistas: poças no chão e gente fechando guarda-chuva. O que causa as duas coisas?","porque":"O texto não diz \"choveu\", mas as poças e os guarda-chuvas mostram isso. É uma informação implícita.","tipo":"opcoes","o":["A escola estava fechada","Chovia ou tinha acabado de chover","Era dia de festa","Fazia um calor forte"],"a":1},{"m":1,"missao":"TERRA","materia":"PORTUGUÊS","aula":"Ler como detetive","p":"Leia: \"Venha para a Astrokdok! Aqui você estuda, viaja pelo espaço e ainda ganha um robô amigo. Inscrições até sexta!\" Qual é a finalidade principal desse texto?","dica":"Repare no \"Venha!\" e nas vantagens que o texto lista. O que ele quer que o leitor FAÇA?","porque":"É uma propaganda: chama o leitor (\"Venha!\"), mostra vantagens e dá um prazo. Tudo para convencer alguém a se inscrever. A data informa, mas está ali para ajudar o convite.","tipo":"opcoes","o":["Informar a hora do recreio","Ensinar a montar um robô","Convencer o leitor a se inscrever","Contar a história do Kdok"],"a":2},{"m":1,"missao":"TERRA","materia":"PORTUGUÊS","aula":"Ler como detetive","p":"Leia: \"Seu Dito foi à feira às 9h e voltou de mãos vazias, reclamando que chegou tarde de novo.\" Qual conclusão NÃO tem apoio no texto?","dica":"Teste cada opção: que palavra do texto serve de pista para ela? A opção sem pista nenhuma é a resposta.","porque":"Voltar de mãos vazias e reclamar do atraso mostram que queria algo e que acabou. O \"de novo\" mostra que já aconteceu antes. Já \"não gosta da feira\" não tem pista: seria inventar.","tipo":"opcoes","o":["Seu Dito queria comprar alguma coisa","Não foi a primeira vez que chegou tarde","O que Seu Dito queria já tinha acabado","Seu Dito não gosta da feira"],"a":3},{"m":1,"missao":"TERRA","materia":"ASTRONOMIA","aula":"O planeta que gira","p":"O movimento da Terra girando em volta de si mesma, que faz o dia e a noite, se chama:","dica":"Pense num pião girando no mesmo lugar. O nome desse movimento parece com \"rodar\".","porque":"Rotação: a Terra gira em volta de si mesma, uma volta a cada 24 horas. A translação é a volta em torno do Sol, que leva 1 ano.","tipo":"opcoes","o":["translação","gravidade","rotação","órbita"],"a":2},{"m":1,"missao":"TERRA","materia":"ASTRONOMIA","aula":"O planeta que gira","p":"Por que o Sol parece nascer sempre do lado leste?","dica":"Lembre: quem se mexe é a Terra. Para que lado ela gira?","porque":"A Terra gira de oeste para leste, então o lado leste é o primeiro a encontrar o Sol de manhã. Parece que o Sol sobe, mas quem gira somos nós.","tipo":"opcoes","o":["Porque a Terra gira de oeste para leste","Porque o Sol dá voltas em torno da Terra","Porque o vento empurra o Sol","Porque é verão"],"a":0},{"m":1,"missao":"TERRA","materia":"ASTRONOMIA","aula":"O planeta que gira","p":"Em qual camada da atmosfera ficam as nuvens e a chuva?","dica":"As nuvens ficam perto do chão, onde a gente vive. Procure a camada mais baixa.","porque":"Troposfera: a camada mais baixa, até uns 12 km. É onde ficam o ar que respiramos, as nuvens, a chuva e os aviões.","tipo":"opcoes","o":["termosfera","mesosfera","estratosfera","troposfera"],"a":3},{"m":1,"missao":"TERRA","materia":"ASTRONOMIA","aula":"O planeta que gira","p":"Quando é meio-dia no Vale do Capão, que horas são, mais ou menos, no lado oposto da Terra?","dica":"Ao meio-dia, o Capão está de frente para o Sol. E o lado de trás da Terra, está virado para onde?","porque":"Se um lado está de frente para o Sol, o lado oposto está de costas para ele: lá é noite, por volta da meia-noite. É a rotação que leva o dia e a noite a todos os lugares.","tipo":"opcoes","o":["Meio-dia também","Por volta da meia-noite","Seis da manhã","Seis da tarde"],"a":1},{"m":1,"missao":"TERRA","materia":"ASTRONOMIA","aula":"O planeta que gira","p":"A Estação Espacial dá uma volta na Terra a cada 90 minutos. Um dia tem 1.440 minutos. Quantas voltas ela dá em um dia?","dica":"Corte um zero dos dois números: 144 ÷ 9. Que número vezes 9 dá 144?","porque":"1.440 ÷ 90 = 144 ÷ 9 = 16 voltas. A cada volta, o Sol nasce uma vez para os astronautas: 16 vezes por dia!","tipo":"numero","n":16,"conta":"1.440 ÷ 90 = ?"},{"m":1,"missao":"TERRA","materia":"GEOGRAFIA · VALE DO CAPÃO","aula":"O vale da base","p":"O Vale do Capão fica em qual estado?","dica":"A capital desse estado é Salvador.","porque":"Bahia, na região Nordeste do Brasil.","tipo":"opcoes","o":["Minas Gerais","Pernambuco","Bahia","Goiás"],"a":2},{"m":1,"missao":"TERRA","materia":"GEOGRAFIA · VALE DO CAPÃO","aula":"O vale da base","p":"Qual cidade foi a primeira capital do Brasil?","dica":"É a capital da Bahia, a uns 450 km do Capão.","porque":"Salvador foi a capital do Brasil de 1549 a 1763. Depois veio o Rio de Janeiro e, a partir de 1960, Brasília.","tipo":"opcoes","o":["Salvador","Rio de Janeiro","Brasília","Palmeiras"],"a":0},{"m":1,"missao":"TERRA","materia":"GEOGRAFIA · VALE DO CAPÃO","aula":"O vale da base","p":"Por que a Cachoeira da Fumaça tem esse nome?","dica":"Imagine a água caindo de 340 metros, com o vento batendo nela.","porque":"A queda é tão alta que o vento espalha a água em gotinhas. De longe, parece fumaça.","tipo":"opcoes","o":["Porque tem um vulcão perto","Porque a água vira névoa antes de chegar embaixo","Porque fazem fogueira lá em cima","Porque a água é quente"],"a":1},{"m":1,"missao":"TERRA","materia":"GEOGRAFIA · VALE DO CAPÃO","aula":"O vale da base","p":"De onde vem o nome \"Diamantina\"?","dica":"Olhe bem a palavra: Diamantina. Que pedra preciosa está escondida nela?","porque":"Diamantes foram encontrados aqui por volta de 1840 e atraíram muitos garimpeiros.","tipo":"opcoes","o":["De uma rainha chamada Diamantina","De uma estrela muito brilhante","De um rio da região","Dos diamantes achados na região"],"a":3},{"m":1,"missao":"TERRA","materia":"GEOGRAFIA · VALE DO CAPÃO","aula":"O vale da base","p":"A cachoeira tem cerca de 340 m. Um prédio de 10 andares tem uns 30 m. Quantos prédios inteiros, um em cima do outro, cabem na altura da cachoeira?","dica":"30 × 10 = 300, e sobram 40 metros. Cabe mais um prédio de 30 nesses 40?","porque":"30 × 11 = 330. Cabem 11 prédios e ainda sobram 10 metros. A Fumaça é alta como um prédio de uns 110 andares!","tipo":"numero","n":11,"conta":"340 ÷ 30 = ?"},{"m":2,"missao":"LUA","materia":"MATEMÁTICA","aula":"Frações","p":"Uma pizza foi cortada em 8 fatias iguais. Você comeu 3. Que fração da pizza você comeu?","dica":"O de baixo (denominador) é em quantas fatias a pizza foi cortada. O de cima (numerador), quantas você pegou.","porque":"3 fatias de 8: 3/8. O 8 é o denominador (as fatias do inteiro) e o 3 é o numerador (as que você comeu).","tipo":"opcoes","o":["3/8","8/3","3/5","5/8"],"a":0},{"m":2,"missao":"LUA","materia":"MATEMÁTICA","aula":"Frações","p":"Na fração 5/6, qual é o denominador?","dica":"O denominador é o número de baixo, que no jogo fica depois da barra. Ele diz em quantas partes o inteiro foi dividido.","porque":"Em 5/6, o 6 é o denominador: o inteiro foi dividido em 6 partes. O 5 é o numerador.","tipo":"numero","n":6,"conta":null},{"m":2,"missao":"LUA","materia":"MATEMÁTICA","aula":"Frações","p":"Qual destas frações é equivalente a 2/3?","dica":"Multiplique o de cima e o de baixo pelo MESMO número. Se só um dos dois mudou, não é equivalente.","porque":"2 × 2 = 4 e 3 × 2 = 6. Então 2/3 = 4/6: a mesma parte do inteiro, só que em pedaços menores.","tipo":"opcoes","o":["3/4","2/6","4/3","4/6"],"a":3},{"m":2,"missao":"LUA","materia":"MATEMÁTICA","aula":"Frações","p":"A trilha até a cachoeira tem 12 km. Você já andou 2/3 do caminho. Quantos km você já andou?","dica":"Primeiro divida 12 por 3: isso é 1/3 do caminho. Depois multiplique por 2.","porque":"12 ÷ 3 = 4 km (um terço). 4 × 2 = 8 km andados. Faltam só 4!","tipo":"numero","n":8,"conta":"2/3 de 12 = ?"},{"m":2,"missao":"LUA","materia":"MATEMÁTICA","aula":"Frações","p":"A Lia bebeu 3/4 de uma garrafa de água. O Tomás bebeu 5/8 de uma garrafa igual. Quem bebeu mais?","dica":"Deixe os denominadores iguais: 3/4 vale quantos oitavos? Multiplique o de cima e o de baixo por 2.","porque":"3/4 = 6/8, e 6/8 é mais que 5/8. A Lia bebeu mais. Quem olhou só o 5 e o 3 esqueceu que os pedaços têm tamanhos diferentes.","tipo":"opcoes","o":["O Tomás","A Lia","Os dois beberam o mesmo tanto"],"a":1},{"m":2,"missao":"LUA","materia":"MATEMÁTICA","aula":"Frações","p":"A nave sai com 240 litros de combustível. Na decolagem ela gasta 1/4 do total e, na viagem, mais 1/3 do total. Quantos litros sobram?","dica":"1/4 de 240 é 240 ÷ 4. 1/3 de 240 é 240 ÷ 3. Some os dois gastos e tire do total.","porque":"240 ÷ 4 = 60 e 240 ÷ 3 = 80. Gastou 60 + 80 = 140. Sobram 240 − 140 = 100 litros.","tipo":"numero","n":100,"conta":null},{"m":2,"missao":"LUA","materia":"ASTRONOMIA","aula":"A Lua","p":"A Lua brilha no céu porque:","dica":"A Lua é como um espelho. De onde vem a luz que um espelho devolve?","porque":"A Lua não tem luz própria: ela reflete a luz do Sol, como um espelho.","tipo":"opcoes","o":["tem luz própria","está pegando fogo","reflete a luz do Sol","é feita de gelo"],"a":2},{"m":2,"missao":"LUA","materia":"ASTRONOMIA","aula":"A Lua","p":"Quem foi o primeiro ser humano a pisar na Lua, em 1969?","dica":"Ele chegou na missão Apollo 11, junto com Buzz Aldrin.","porque":"Neil Armstrong, em 1969. Yuri Gagarin foi o primeiro a ir ao espaço, e Marcos Pontes, o primeiro brasileiro. O Buzz Lightyear ainda está treinando.","tipo":"opcoes","o":["Yuri Gagarin","Neil Armstrong","Marcos Pontes","Buzz Lightyear"],"a":1},{"m":2,"missao":"LUA","materia":"ASTRONOMIA","aula":"A Lua","p":"Por que as pegadas da Apollo 11 continuam na Lua até hoje?","dica":"Aqui na Terra, o que apaga uma pegada na areia?","porque":"Na Terra, o vento e a chuva apagam as pegadas. Na Lua não há ar, então não há vento nem chuva para apagar nada.","tipo":"opcoes","o":["Porque na Lua não tem vento nem chuva","Porque alguém cuida delas","Porque o chão é de cimento","Porque a Lua é fria"],"a":0},{"m":2,"missao":"LUA","materia":"ASTRONOMIA","aula":"A Lua","p":"O que causa as fases da Lua?","dica":"O Sol sempre ilumina metade da Lua. O que muda é o jeito como a gente enxerga essa metade.","porque":"A Lua gira em volta da Terra, e a cada noite vemos um pedaço diferente da metade iluminada. A sombra da Terra só aparece no eclipse lunar.","tipo":"opcoes","o":["A sombra da Terra cobrindo a Lua","Nuvens passando na frente dela","A Lua acende e apaga sozinha","A parte iluminada que a gente vê muda enquanto a Lua gira em volta da Terra"],"a":3},{"m":2,"missao":"LUA","materia":"ASTRONOMIA","aula":"A Lua","p":"Na Lua a gravidade é 6 vezes mais fraca. Um astronauta com traje marca 120 kg na balança da Terra. Quanto a balança marcaria na Lua?","dica":"6 vezes mais fraca: divida por 6. Ajuda lembrar que 12 ÷ 6 = 2.","porque":"120 ÷ 6 = 20 kg. A massa do astronauta não muda, mas a Lua puxa bem menos, então o peso que a balança mostra cai. Por isso dá para pular tão alto!","tipo":"numero","n":20,"conta":"120 ÷ 6 = ?"},{"m":2,"missao":"LUA","materia":"GEOGRAFIA · MARANHÃO","aula":"A base perto do Equador","p":"Qual é a capital do Maranhão?","dica":"Ela fica do outro lado da baía, bem em frente a Alcântara, e foi fundada pelos franceses.","porque":"São Luís é a capital do Maranhão. Belém é a do Pará, Fortaleza a do Ceará e Teresina a do Piauí.","tipo":"opcoes","o":["Belém","São Luís","Fortaleza","Teresina"],"a":1},{"m":2,"missao":"LUA","materia":"GEOGRAFIA · MARANHÃO","aula":"A base perto do Equador","p":"As lagoas dos Lençóis Maranhenses se formam principalmente com:","dica":"Lembre da época do ano em que as lagoas enchem.","porque":"Na época das chuvas, a água se junta nos buracos entre as dunas e forma as lagoas. Na seca, elas vão baixando.","tipo":"opcoes","o":["água do mar","neve derretida","água de poço","água da chuva"],"a":3},{"m":2,"missao":"LUA","materia":"GEOGRAFIA · MARANHÃO","aula":"A base perto do Equador","p":"Por que Alcântara é um ótimo lugar para lançar foguetes?","dica":"Pense no empurrão que a Terra dá no foguete. Onde o chão gira mais rápido?","porque":"Perto do Equador, o chão gira mais rápido. Esse empurrão ajuda o foguete a subir e economiza combustível.","tipo":"opcoes","o":["Fica perto da Linha do Equador","Tem muitas montanhas","Faz muito frio","Fica perto do Polo Sul"],"a":0},{"m":2,"missao":"LUA","materia":"GEOGRAFIA · MARANHÃO","aula":"A base perto do Equador","p":"O que é o Bumba-meu-boi?","dica":"Lembre das fantasias coloridas e da música.","porque":"É uma festa popular tão importante que virou Patrimônio Cultural Imaterial da Humanidade.","tipo":"opcoes","o":["Um tipo de foguete","Uma comida típica","Uma festa com música, dança e a história de um boi","Um rio do Maranhão"],"a":2},{"m":2,"missao":"LUA","materia":"GEOGRAFIA · MARANHÃO","aula":"A base perto do Equador","p":"São Luís foi fundada pelos franceses em 1612. Quantos anos ela completa em 2026?","dica":"De 1612 até 2012 são 400 anos. Depois, conte de 2012 até 2026.","porque":"2026 − 1612 = 414 anos: 4 séculos (400 anos) e mais 14.","tipo":"numero","n":414,"conta":"2026 − 1612 = ?"},{"m":3,"missao":"SOL","materia":"INGLÊS","aula":"Space words","p":"Como se diz \"foguete\" em inglês?","dica":"MOON é Lua, STAR é estrela, SUN é Sol. Sobrou qual?","porque":"ROCKET = foguete.","tipo":"opcoes","o":["moon","star","rocket","sun"],"a":2},{"m":3,"missao":"SOL","materia":"INGLÊS","aula":"Space words","p":"Complete: The Sun ___ a star.","dica":"The Sun é UMA coisa só. Para uma coisa, usamos is ou are?","porque":"Uma coisa só (the Sun) pede IS: The Sun is a star. O Sol é uma estrela.","tipo":"opcoes","o":["are","is","am"],"a":1},{"m":3,"missao":"SOL","materia":"INGLÊS","aula":"Space words","p":"Complete: The planets ___ round.","dica":"Planets termina com S: são vários planetas. Para várias coisas, usamos...","porque":"Várias coisas (the planets) pedem ARE: The planets are round. Os planetas são redondos.","tipo":"opcoes","o":["is","am","are"],"a":2},{"m":3,"missao":"SOL","materia":"INGLÊS","aula":"Space words","p":"O que quer dizer \"The Moon is cold at night\"?","dica":"Moon = Lua, cold = frio, night = noite.","porque":"The Moon (a Lua) is (é) cold (fria) at night (à noite). E é mesmo: a noite da Lua chega a 170 graus abaixo de zero!","tipo":"opcoes","o":["A Lua é fria à noite","A Lua é grande de dia","A Lua está longe","A Lua é quente à noite"],"a":0},{"m":3,"missao":"SOL","materia":"INGLÊS","aula":"Space words","p":"Complete: Kdok ___ popcorn every day. (O verbo é to make: fazer.)","dica":"Kdok é um só: é como dizer he (ele). Com he, she e it, o verbo do presente simples ganha...","porque":"Com um só (he, she, it ou um nome como Kdok), o verbo ganha S: Kdok makes popcorn every day. O Kdok faz pipoca todo dia.","tipo":"opcoes","o":["make","makes","are make","making"],"a":1},{"m":3,"missao":"SOL","materia":"INGLÊS","aula":"Space words","p":"Qual destas frases está CORRETA?","dica":"Confira: I pede am; uma coisa pede is; várias pedem are; e com he, she, it o verbo ganha S.","porque":"The Earth é uma coisa só, então o verbo ganha S: turns. As outras erram: o certo é I am a cadet e The stars are far away.","tipo":"opcoes","o":["The Earth turn around the Sun.","I is a cadet.","The stars is far away.","The Earth turns around the Sun."],"a":3},{"m":3,"missao":"SOL","materia":"ASTRONOMIA","aula":"A nossa estrela","p":"O Sol é:","dica":"Ele produz a própria luz, como as estrelinhas do céu à noite.","porque":"O Sol é uma estrela: a mais perto de nós. Planetas e luas não têm luz própria.","tipo":"opcoes","o":["um planeta","uma lua","uma estrela","um cometa"],"a":2},{"m":3,"missao":"SOL","materia":"ASTRONOMIA","aula":"A nossa estrela","p":"O que você NUNCA deve fazer?","dica":"Uma dessas coisas pode machucar os olhos para sempre.","porque":"Nunca olhe direto para o Sol, nem de óculos escuros: a luz forte pode ferir os olhos para sempre.","tipo":"opcoes","o":["Olhar direto para o Sol","Usar protetor solar","Ficar na sombra","Estudar o Sol em livros"],"a":0},{"m":3,"missao":"SOL","materia":"ASTRONOMIA","aula":"A nossa estrela","p":"Se as estrelas do céu à noite também são sóis, por que elas parecem só pontinhos?","dica":"Pense no farol de um carro: de perto é grande; lá longe na estrada, vira um pontinho.","porque":"Elas são sóis, algumas até maiores que o nosso, mas estão tão longe que parecem pontinhos. De dia não aparecem porque a luz do Sol as esconde.","tipo":"opcoes","o":["Porque são muito pequenas","Porque estão muito mais longe que o Sol","Porque só acendem à noite","Porque são feitas de gelo"],"a":1},{"m":3,"missao":"SOL","materia":"ASTRONOMIA","aula":"A nossa estrela","p":"As auroras acontecem quando:","dica":"As auroras aparecem perto dos polos e têm a ver com as partículas que o Sol sopra.","porque":"As partículas do vento solar, guiadas pelo campo magnético, esbarram no ar perto dos polos, e o céu se acende em cores.","tipo":"opcoes","o":["a Lua fica cheia","chove muito","um vulcão explode","as partículas do vento solar chegam ao ar perto dos polos"],"a":3},{"m":3,"missao":"SOL","materia":"ASTRONOMIA","aula":"A nossa estrela","p":"A luz do Sol leva 8 minutos e 20 segundos para chegar à Terra. Quantos segundos são?","dica":"Cada minuto tem 60 segundos. Faça 8 × 60 e depois some os 20 segundos.","porque":"8 × 60 = 480 segundos, e 480 + 20 = 500 segundos. A luz que bate na sua pele agora saiu do Sol há 500 segundos!","tipo":"numero","n":500,"conta":"8 × 60 + 20 = ?"},{"m":3,"missao":"SOL","materia":"GEOGRAFIA · CHILE","aula":"O deserto dos telescópios","p":"Que língua se fala no Chile?","dica":"A Dra. Paz disse \"¡Hola!\" e \"Soy la Doctora\".","porque":"No Chile se fala espanhol, como na maior parte dos países da América do Sul. O Brasil é o grande país do continente que fala português.","tipo":"opcoes","o":["português","espanhol","inglês","francês"],"a":1},{"m":3,"missao":"SOL","materia":"GEOGRAFIA · CHILE","aula":"O deserto dos telescópios","p":"O que quer dizer \"cielo\"?","dica":"É onde ficam as estrelas que os telescópios observam.","porque":"Cielo = céu. Parecido com o português, não é?","tipo":"opcoes","o":["cinco","cidade","sol","céu"],"a":3},{"m":3,"missao":"SOL","materia":"GEOGRAFIA · CHILE","aula":"O deserto dos telescópios","p":"Por que tantos telescópios ficam no Atacama?","dica":"O que atrapalha quem quer ver as estrelas? Pense em nuvens e em luzes.","porque":"Céu sem nuvens, ar seco e lugar alto: a luz das estrelas chega mais limpa. É o sonho de todo astrônomo.","tipo":"opcoes","o":["Porque o ar é seco, o lugar é alto e quase não tem nuvens","Porque é perto do mar","Porque faz muito calor","Porque tem muitas cidades iluminadas"],"a":0},{"m":3,"missao":"SOL","materia":"GEOGRAFIA · CHILE","aula":"O deserto dos telescópios","p":"O Chile fica entre a Cordilheira dos Andes e qual oceano?","dica":"O Brasil é banhado pelo Atlântico. O Chile fica do outro lado da América do Sul.","porque":"O Oceano Pacífico banha todo o lado oeste do Chile. O Atlântico fica do lado do Brasil.","tipo":"opcoes","o":["Atlântico","Índico","Pacífico","Ártico"],"a":2},{"m":3,"missao":"SOL","materia":"GEOGRAFIA · CHILE","aula":"O deserto dos telescópios","p":"Quais são os dois únicos países da América do Sul que NÃO fazem fronteira com o Brasil?","dica":"Um deles é o país onde estamos agora. O outro tem o nome da linha que divide a Terra em norte e sul.","porque":"Chile e Equador. Todos os outros países da América do Sul encostam no Brasil em algum ponto.","tipo":"opcoes","o":["Peru e Equador","Chile e Equador","Chile e Argentina","Uruguai e Paraguai"],"a":1},{"m":4,"missao":"MERCÚRIO","materia":"MATEMÁTICA","aula":"Porcentagem","p":"A bateria do seu celular está em 50%. Quanto da bateria ainda tem?","dica":"50% quer dizer 50 de cada 100. Que parte de 100 é 50?","porque":"50% = 50 de cada 100 = a metade.","tipo":"opcoes","o":["A metade","Um quarto","A bateria inteira","Quase nada"],"a":0},{"m":4,"missao":"MERCÚRIO","materia":"MATEMÁTICA","aula":"Porcentagem","p":"Quanto é 10% de 150?","dica":"10% é a décima parte. Divida 150 por 10.","porque":"150 ÷ 10 = 15.","tipo":"numero","n":15,"conta":"10% de 150 = ?"},{"m":4,"missao":"MERCÚRIO","materia":"MATEMÁTICA","aula":"Porcentagem","p":"Uma camiseta na feira do Capão custa R$ 40 e está com 25% de desconto. Quantos reais é o desconto?","dica":"25% é um quarto. Divida 40 por 4.","porque":"40 ÷ 4 = 10. O desconto é R$ 10.","tipo":"numero","n":10,"conta":null},{"m":4,"missao":"MERCÚRIO","materia":"MATEMÁTICA","aula":"Porcentagem","p":"JACI ficou na dúvida e te perguntou: \"10% de 50 é 10?\". O que você responde?","dica":"10% é a décima parte. Quanto é 50 ÷ 10?","porque":"50 ÷ 10 = 5. O \"10\" do 10% é a parte de cada 100, não a resposta.","tipo":"opcoes","o":["Sim: 10% é sempre 10","Não: 10% de 50 é 5","Não: 10% de 50 é 50"],"a":1},{"m":4,"missao":"MERCÚRIO","materia":"MATEMÁTICA","aula":"Porcentagem","p":"Numa escola de 300 alunos, 15% vão de ônibus. Quantos alunos vão de ônibus?","dica":"10% de 300 é 30. 5% é a metade disso. Some os dois.","porque":"10% = 30 e 5% = 15. Então 15% = 30 + 15 = 45 alunos.","tipo":"numero","n":45,"conta":null},{"m":4,"missao":"MERCÚRIO","materia":"MATEMÁTICA","aula":"Porcentagem","p":"A Escola do Capão arrecadou R$ 2.500 na festa junina. 40% vai para a excursão. Quantos reais vão para a excursão?","dica":"1% de 2.500 é 2.500 ÷ 100 = 25. Multiplique por 40.","porque":"2.500 ÷ 100 = 25. 25 × 40 = R$ 1.000.","tipo":"numero","n":1000,"conta":"40% de 2.500 = ?"},{"m":4,"missao":"MERCÚRIO","materia":"ASTRONOMIA","aula":"Mercúrio, o mensageiro","p":"Qual é o planeta mais perto do Sol?","dica":"É o primeiro da fila, o planeta desta missão.","porque":"Mercúrio é o primeiro planeta a partir do Sol.","tipo":"opcoes","o":["Vênus","Terra","Mercúrio","Marte"],"a":2},{"m":4,"missao":"MERCÚRIO","materia":"ASTRONOMIA","aula":"Mercúrio, o mensageiro","p":"Por que Mercúrio fica tão frio à noite, mesmo perto do Sol?","dica":"Pense no cobertor: o que guarda o calor de um planeta?","porque":"Sem atmosfera, que funciona como um cobertor de ar, o calor foge para o espaço quando o Sol se põe.","tipo":"opcoes","o":["Porque tem neve","Porque quase não tem atmosfera para guardar o calor","Porque gira muito rápido","Porque fica longe do Sol"],"a":1},{"m":4,"missao":"MERCÚRIO","materia":"ASTRONOMIA","aula":"Mercúrio, o mensageiro","p":"De dia, Mercúrio chega a 430 °C. À noite, cai a 180 °C abaixo de zero. Quantos graus separam as duas temperaturas?","dica":"De −180 até 0 são 180 graus. De 0 até 430 são mais 430. Some os dois.","porque":"180 + 430 = 610 graus de diferença!","tipo":"numero","n":610,"conta":"430 − (−180) = ?"},{"m":4,"missao":"MERCÚRIO","materia":"ASTRONOMIA","aula":"Mercúrio, o mensageiro","p":"Um ano de Mercúrio dura 88 dias. Quantos anos COMPLETOS de Mercúrio cabem em 1 ano da Terra (365 dias)?","dica":"88 × 4 = 352. E 88 × 5, passa de 365?","porque":"88 × 4 = 352 e 88 × 5 = 440, que já passa de 365. Então cabem 4 anos completos, e sobram 13 dias.","tipo":"numero","n":4,"conta":null},{"m":4,"missao":"MERCÚRIO","materia":"ASTRONOMIA","aula":"Mercúrio, o mensageiro","p":"Em Mercúrio, de um nascer do Sol até o outro passam 176 dias da Terra. Quantos anos de Mercúrio (88 dias cada) cabem nesse único dia?","dica":"Quantas vezes 88 cabe em 176? Experimente 88 + 88.","porque":"88 + 88 = 176. Um dia de Mercúrio dura 2 anos de Mercúrio: lá, o dia é mais longo que o ano!","tipo":"numero","n":2,"conta":"176 ÷ 88 = ?"},{"m":4,"missao":"MERCÚRIO","materia":"HISTÓRIA · ITÁLIA","aula":"Os deuses do céu","p":"Qual é a capital da Itália?","dica":"É a cidade onde você está agora, a cidade do Coliseu.","porque":"Roma, a cidade eterna, é a capital da Itália.","tipo":"opcoes","o":["Milão","Roma","Paris","Veneza"],"a":1},{"m":4,"missao":"MERCÚRIO","materia":"HISTÓRIA · ITÁLIA","aula":"Os deuses do céu","p":"O planeta Mercúrio tem o nome de qual deus romano?","dica":"Mercúrio é o planeta mais rápido. Qual deus combina com isso?","porque":"Mercúrio era o mensageiro dos deuses. Por isso o planeta mais rápido ganhou o nome dele!","tipo":"opcoes","o":["O deus da guerra","O deus do mar","O mensageiro, que corria muito rápido","O rei dos deuses"],"a":2},{"m":4,"missao":"MERCÚRIO","materia":"HISTÓRIA · ITÁLIA","aula":"Os deuses do céu","p":"Que número é XIX?","dica":"Separe em duas partes: X e IX. Quanto vale cada uma?","porque":"X = 10 e IX = 10 − 1 = 9. Então 10 + 9 = 19.","tipo":"numero","n":19,"conta":null},{"m":4,"missao":"MERCÚRIO","materia":"HISTÓRIA · ITÁLIA","aula":"Os deuses do céu","p":"Qual planeta tem o nome do deus romano da guerra?","dica":"É o planeta vermelho, cor de sangue.","porque":"Marte era o deus da guerra. O planeta vermelho lembrou os romanos do sangue das batalhas.","tipo":"opcoes","o":["Marte","Vênus","Júpiter","Saturno"],"a":0},{"m":4,"missao":"MERCÚRIO","materia":"HISTÓRIA · ITÁLIA","aula":"Os deuses do céu","p":"Que número é XLIX?","dica":"Separe em XL e IX. Em XL, o X (10) vem antes do L (50): subtrai.","porque":"XL = 50 − 10 = 40 e IX = 10 − 1 = 9. Então 40 + 9 = 49.","tipo":"numero","n":49,"conta":null},{"m":5,"missao":"VÊNUS","materia":"PORTUGUÊS","aula":"Classes de palavras","p":"Na frase \"Vênus brilha no céu\", qual palavra é um VERBO?","dica":"Procure a palavra que diz a AÇÃO, o que Vênus faz.","porque":"\"Brilha\" é a ação: é o verbo. \"Vênus\" e \"céu\" dão nome às coisas: são substantivos.","tipo":"opcoes","o":["Vênus","céu","brilha"],"a":2},{"m":5,"missao":"VÊNUS","materia":"PORTUGUÊS","aula":"Classes de palavras","p":"Qual destas palavras é um ADJETIVO?","dica":"O adjetivo dá uma característica. Qual palavra diz como uma coisa é?","porque":"\"Quente\" é característica: planeta quente. \"Planeta\" é substantivo, \"girar\" é verbo e \"ontem\" é advérbio.","tipo":"opcoes","o":["planeta","quente","girar","ontem"],"a":1},{"m":5,"missao":"VÊNUS","materia":"PORTUGUÊS","aula":"Classes de palavras","p":"Na frase \"As nuvens amarelas cobrem Vênus\", qual palavra é um ADJETIVO?","dica":"Qual palavra diz COMO são as nuvens?","porque":"\"Amarelas\" é a característica das nuvens: é adjetivo. \"Nuvens\" e \"Vênus\" são substantivos, e \"cobrem\" é verbo.","tipo":"opcoes","o":["nuvens","cobrem","Vênus","amarelas"],"a":3},{"m":5,"missao":"VÊNUS","materia":"PORTUGUÊS","aula":"Classes de palavras","p":"Na frase \"A sonda desceu lentamente\", a palavra \"lentamente\" é:","dica":"Ela diz COMO a sonda desceu. Ela está ligada ao verbo ou ao substantivo?","porque":"\"Lentamente\" diz como foi a ação de descer: muda o sentido do verbo. É advérbio de modo.","tipo":"opcoes","o":["advérbio","adjetivo","substantivo","verbo"],"a":0},{"m":5,"missao":"VÊNUS","materia":"PORTUGUÊS","aula":"Classes de palavras","p":"Na frase \"Hoje a nave voou muito\", as palavras \"hoje\" e \"muito\" são:","dica":"\"Hoje\" diz QUANDO a nave voou. \"Muito\" diz QUANTO. Que classe faz esse trabalho?","porque":"\"Hoje\" é advérbio de tempo e \"muito\" é advérbio de intensidade. Os dois mudam o sentido da ação de voar.","tipo":"opcoes","o":["adjetivos","substantivos","advérbios","verbos"],"a":2},{"m":5,"missao":"VÊNUS","materia":"PORTUGUÊS","aula":"Classes de palavras","p":"Em qual frase a palavra \"rápido\" é um ADVÉRBIO?","dica":"Quando \"rápido\" diz como é uma coisa, é adjetivo. Quando diz como a ação aconteceu, é advérbio. Em qual frase ele está ligado ao verbo?","porque":"Em \"a sonda desceu rápido\", a palavra diz como ela desceu: é o mesmo que \"rapidamente\", um advérbio. Nas outras, \"rápido\" é característica do foguete e do planeta: adjetivo.","tipo":"opcoes","o":["O foguete rápido decolou.","Mercúrio é um planeta rápido.","A sonda desceu rápido."],"a":2},{"m":5,"missao":"VÊNUS","materia":"ASTRONOMIA","aula":"Vênus, o planeta estufa","p":"Qual é o planeta MAIS QUENTE do Sistema Solar?","dica":"Não é o mais perto do Sol. É o planeta desta missão, o do efeito estufa.","porque":"Vênus chega a 465 °C, por causa do efeito estufa. Mercúrio fica mais perto do Sol, mas chega \"só\" a 430 °C.","tipo":"opcoes","o":["Mercúrio","Marte","Vênus","Júpiter"],"a":2},{"m":5,"missao":"VÊNUS","materia":"ASTRONOMIA","aula":"Vênus, o planeta estufa","p":"A \"Estrela d'Alva\", que brilha forte de manhãzinha, na verdade é:","dica":"Ela não tem luz própria: reflete a luz do Sol. É um planeta vizinho da Terra.","porque":"É Vênus, refletindo a luz do Sol. Depois do Sol e da Lua, é o ponto mais brilhante do céu.","tipo":"opcoes","o":["uma estrela gigante","o planeta Vênus","um satélite","a Lua"],"a":1},{"m":5,"missao":"VÊNUS","materia":"ASTRONOMIA","aula":"Vênus, o planeta estufa","p":"O que deixa Vênus tão quente?","dica":"Lembre do carro fechado no sol. O que acontece com o calor?","porque":"O ar de Vênus, cheio de gás carbônico, funciona como um cobertor que não deixa o calor sair. Vênus nem é o planeta mais perto do Sol.","tipo":"opcoes","o":["Estar mais perto do Sol que Mercúrio","Vulcões de lava em todo lugar","Ter muitas luas","O efeito estufa: o ar grosso prende o calor"],"a":3},{"m":5,"missao":"VÊNUS","materia":"ASTRONOMIA","aula":"Vênus, o planeta estufa","p":"Em Vênus, o Sol nasce de que lado?","dica":"Na Terra, o Sol nasce no leste. Vênus gira para o lado oposto.","porque":"Vênus gira ao contrário da Terra, então lá o Sol nasce no oeste e se põe no leste.","tipo":"opcoes","o":["No leste, como na Terra","No oeste, porque Vênus gira ao contrário","Não nasce: Vênus não gira"],"a":1},{"m":5,"missao":"VÊNUS","materia":"ASTRONOMIA","aula":"Vênus, o planeta estufa","p":"Vênus leva 243 dias para dar um giro completo em torno de si mesmo e 225 dias para dar a volta no Sol. Quantos dias o giro demora A MAIS que o ano?","dica":"O giro é o número maior. Tire o ano do giro: 243 − 225.","porque":"243 − 225 = 18 dias. Em Vênus, um giro demora mais que o ano inteiro!","tipo":"numero","n":18,"conta":"243 − 225 = ?"},{"m":5,"missao":"VÊNUS","materia":"GEOGRAFIA · AMAZONAS","aula":"A floresta que cuida do clima","p":"Manaus é a capital de qual estado?","dica":"O estado tem o mesmo nome do grande rio e da floresta.","porque":"Manaus é a capital do Amazonas, na região Norte.","tipo":"opcoes","o":["Pará","Acre","Amazonas","Roraima"],"a":2},{"m":5,"missao":"VÊNUS","materia":"GEOGRAFIA · AMAZONAS","aula":"A floresta que cuida do clima","p":"A Floresta Amazônica é:","dica":"Ela é famosa no mundo inteiro pelo tamanho.","porque":"É a maior floresta tropical do mundo, e a maior parte dela fica no Brasil.","tipo":"opcoes","o":["um deserto","a maior floresta tropical do mundo","uma cadeia de montanhas","uma floresta pequena"],"a":1},{"m":5,"missao":"VÊNUS","materia":"GEOGRAFIA · AMAZONAS","aula":"A floresta que cuida do clima","p":"O que é o Encontro das Águas?","dica":"Lembre das cores: um rio escuro e outro barrento, lado a lado.","porque":"O Rio Negro e o Solimões correm lado a lado sem se misturar, porque as águas são diferentes. Depois formam o Rio Amazonas.","tipo":"opcoes","o":["Uma cachoeira","Uma festa do rio","Um lago sem saída","Dois rios que correm juntos sem se misturar por quilômetros"],"a":3},{"m":5,"missao":"VÊNUS","materia":"GEOGRAFIA · AMAZONAS","aula":"A floresta que cuida do clima","p":"As árvores ajudam a combater o efeito estufa porque:","dica":"Que gás deixa Vênus tão quente? As árvores usam esse gás para crescer.","porque":"Elas tiram gás carbônico do ar para crescer e guardam o carbono no corpo delas. Menos gás no ar, menos calor preso.","tipo":"opcoes","o":["fazem sombra","esfriam os rios","absorvem gás carbônico do ar","atraem chuva de pedra"],"a":2},{"m":5,"missao":"VÊNUS","materia":"GEOGRAFIA · AMAZONAS","aula":"A floresta que cuida do clima","p":"Um avião sai de Brasília às 10 h, na hora de Brasília, e voa 3 horas até Manaus. Que horas são em Manaus quando ele pousa?","dica":"Primeiro some a viagem: 10 + 3 dá a hora em Brasília. Depois lembre que Manaus fica 1 hora atrás.","porque":"10 + 3 = 13 h em Brasília. Manaus está 1 hora atrás: 13 − 1 = 12 h.","tipo":"numero","n":12,"conta":null},{"m":6,"missao":"MARTE","materia":"MATEMÁTICA","aula":"Razão e proporção","p":"No laboratório há 6 meninas e 9 meninos. A razão entre meninas e meninos, escrita como fração, é:","dica":"O primeiro que a frase diz fica em cima: meninas para meninos.","porque":"Meninas para meninos: 6/9, que vale o mesmo que 2/3.","tipo":"opcoes","o":["6/9","9/6","6/15"],"a":0},{"m":6,"missao":"MARTE","materia":"MATEMÁTICA","aula":"Razão e proporção","p":"O jipe-robô andou 20 metros em 4 minutos. Quantos metros ele anda por minuto?","dica":"Razão é uma divisão: os metros divididos pelos minutos.","porque":"20 ÷ 4 = 5 metros por minuto.","tipo":"numero","n":5,"conta":"20 ÷ 4 = ?"},{"m":6,"missao":"MARTE","materia":"MATEMÁTICA","aula":"Razão e proporção","p":"JACI vai fazer suco para a turma toda com 4 copos de polpa. Na receita, 1 copo de polpa pede 3 copos de água. Quantos copos de água vão no suco?","dica":"Multiplique em cruz: 1 × x = 3 × 4.","porque":"1 × x = 3 × 4 = 12. São 12 copos de água.","tipo":"numero","n":12,"conta":"1/3 = 4/x"},{"m":6,"missao":"MARTE","materia":"MATEMÁTICA","aula":"Razão e proporção","p":"Qual razão é equivalente a 2/5?","dica":"Multiplique o de cima E o de baixo pelo mesmo número: 2 × 2 e 5 × 2.","porque":"2 × 2 = 4 e 5 × 2 = 10. Então 4/10 vale o mesmo que 2/5.","tipo":"opcoes","o":["4/7","4/10","2/10","5/2"],"a":1},{"m":6,"missao":"MARTE","materia":"MATEMÁTICA","aula":"Razão e proporção","p":"Num mapa de escala 1:50.000, a trilha até a cachoeira mede 6 cm. Quantos km tem a trilha de verdade?","dica":"1 cm no mapa vale 50.000 cm, que são 500 m. Faça 6 × 500 e depois passe os metros para km.","porque":"6 × 500 = 3.000 m = 3 km.","tipo":"numero","n":3,"conta":"escala 1:50.000 · 6 cm = ? km"},{"m":6,"missao":"MARTE","materia":"MATEMÁTICA","aula":"Razão e proporção","p":"A nave gasta 30 litros de combustível a cada 100 km. Quantos litros ela gasta em 450 km?","dica":"Multiplique em cruz: 100 × x = 30 × 450. Depois divida por 100.","porque":"30 × 450 = 13.500. 13.500 ÷ 100 = 135 litros.","tipo":"numero","n":135,"conta":"30/100 = x/450"},{"m":6,"missao":"MARTE","materia":"ASTRONOMIA","aula":"O planeta vermelho","p":"Por que Marte é vermelho?","dica":"Pense num prego velho, esquecido na chuva. Que cor ele fica?","porque":"O ferro das rochas e da poeira enferrujou. Ferrugem é vermelha!","tipo":"opcoes","o":["Porque está pegando fogo","Porque o chão tem ferrugem (óxido de ferro)","Porque o Sol é vermelho lá","Porque é coberto de lava"],"a":1},{"m":6,"missao":"MARTE","materia":"ASTRONOMIA","aula":"O planeta vermelho","p":"Quais são as luas de Marte?","dica":"São duas luazinhas tortas, parecidas com batatas.","porque":"Fobos e Deimos. Io e Europa são luas de Júpiter, e Titã e Encélado são luas de Saturno.","tipo":"opcoes","o":["Io e Europa","Titã e Encélado","Não tem luas","Fobos e Deimos"],"a":3},{"m":6,"missao":"MARTE","materia":"ASTRONOMIA","aula":"O planeta vermelho","p":"O Monte Olimpo, em Marte, tem uns 22 km de altura. O Everest tem uns 9 km. Quantos km o Monte Olimpo é mais alto?","dica":"Tire a altura do Everest da altura do Monte Olimpo.","porque":"22 − 9 = 13 km a mais. O maior vulcão do Sistema Solar!","tipo":"numero","n":13,"conta":"22 − 9 = ?"},{"m":6,"missao":"MARTE","materia":"ASTRONOMIA","aula":"O planeta vermelho","p":"Por que os cientistas ficam tão animados quando acham gelo em Marte?","dica":"O que acontece com o gelo quando ele derrete? E do que todo ser vivo precisa?","porque":"Gelo derretido vira água, para beber e plantar. E onde já houve água, pode ter existido vida.","tipo":"opcoes","o":["Porque o gelo deixa Marte mais quente","Porque gelo derretido vira água, e os astronautas vão precisar de água","Porque o gelo é vermelho","Porque o gelo faz Marte girar"],"a":1},{"m":6,"missao":"MARTE","materia":"ASTRONOMIA","aula":"O planeta vermelho","p":"Um ano de Marte dura 687 dias. Imagine que você tem 14 anos da Terra, uns 5.110 dias. Quantos aniversários COMPLETOS de Marte você já teria feito?","dica":"Veja quantas vezes 687 cabe em 5.110. Experimente: 687 × 7 = 4.809 e 687 × 8 = 5.496.","porque":"687 × 7 = 4.809, que cabe em 5.110. 687 × 8 = 5.496, que já passa. Então são 7 aniversários de Marte. Como o ano de lá é mais longo, a idade em Marte é bem menor!","tipo":"numero","n":7,"conta":null},{"m":6,"missao":"MARTE","materia":"GEOGRAFIA · EUA","aula":"A costa dos foguetes","p":"Qual é a capital dos Estados Unidos?","dica":"Cuidado: não é a maior cidade do país.","porque":"Washington. Nova York é a maior cidade, mas não é a capital. E Flórida é um estado.","tipo":"opcoes","o":["Nova York","Los Angeles","Washington","Flórida"],"a":2},{"m":6,"missao":"MARTE","materia":"GEOGRAFIA · EUA","aula":"A costa dos foguetes","p":"Os Estados Unidos ficam em qual continente?","dica":"É o mesmo continente do Brasil, só que na parte de cima.","porque":"Na América, na parte do norte. O Brasil fica na América do Sul.","tipo":"opcoes","o":["Europa","América","Ásia","África"],"a":1},{"m":6,"missao":"MARTE","materia":"GEOGRAFIA · EUA","aula":"A costa dos foguetes","p":"Quantos estados têm os Estados Unidos?","dica":"Conte as estrelas da bandeira: uma para cada estado.","porque":"50 estados: por isso a bandeira tem 50 estrelas.","tipo":"numero","n":50,"conta":null},{"m":6,"missao":"MARTE","materia":"GEOGRAFIA · EUA","aula":"A costa dos foguetes","p":"\"Countdown\" quer dizer:","dica":"É o que todo mundo grita antes de o foguete subir: três, dois, um...","porque":"Countdown é a contagem regressiva: three, two, one...","tipo":"opcoes","o":["lançamento","foguete","astronauta","contagem regressiva"],"a":3},{"m":6,"missao":"MARTE","materia":"GEOGRAFIA · EUA","aula":"A costa dos foguetes","p":"Num lançamento de foguete, o que acontece primeiro?","dica":"Traduza as duas palavras. Primeiro a gente conta, ou primeiro o foguete sai do chão?","porque":"Primeiro o countdown, a contagem regressiva (três, dois, um), e depois o liftoff, a decolagem.","tipo":"opcoes","o":["O LIFTOFF, e depois o COUNTDOWN","O COUNTDOWN, e depois o LIFTOFF","Os dois ao mesmo tempo"],"a":1},{"m":7,"missao":"ASTEROIDES","materia":"CIÊNCIAS","aula":"Os estados da matéria","p":"A água do copo tem volume fixo, mas pega a forma do copo. Ela está em qual estado físico?","dica":"Ela escorre e se ajeita no formato do recipiente, mas não se espalha para encher a sala toda.","porque":"Líquido: volume fixo e a forma do recipiente. Um gás encheria a sala toda, e um sólido teria forma própria.","tipo":"opcoes","o":["sólido","gasoso","líquido"],"a":2},{"m":7,"missao":"ASTEROIDES","materia":"CIÊNCIAS","aula":"Os estados da matéria","p":"O picolé derretendo na sua mão passa de sólido para líquido. Como se chama essa mudança?","dica":"É a mudança que acontece quando o gelo recebe calor e vira água.","porque":"Fusão é a passagem do sólido para o líquido. A solidificação é o caminho contrário, do líquido para o sólido.","tipo":"opcoes","o":["solidificação","fusão","condensação","sublimação"],"a":1},{"m":7,"missao":"ASTEROIDES","materia":"CIÊNCIAS","aula":"Os estados da matéria","p":"De manhã cedo, aparecem gotinhas de água na grama do Capão: o orvalho. O vapor de água do ar esfriou e virou líquido. Que mudança é essa?","dica":"O vapor é gás, e ele virou líquido. Qual nome vai do gasoso para o líquido?","porque":"Condensação: do gasoso para o líquido. É o mesmo que deixa molhado, por fora, um copo de água gelada.","tipo":"opcoes","o":["condensação","vaporização","fusão","sublimação"],"a":0},{"m":7,"missao":"ASTEROIDES","materia":"CIÊNCIAS","aula":"Os estados da matéria","p":"A água do pote está a 25 °C. Ao nível do mar, quantos graus ela ainda precisa esquentar para começar a ferver?","dica":"Ao nível do mar, a água ferve a 100 °C. Quanto falta do 25 até chegar no 100?","porque":"100 − 25 = 75 graus a mais. Aí começa a ebulição.","tipo":"numero","n":75,"conta":"100 − 25 = ?"},{"m":7,"missao":"ASTEROIDES","materia":"CIÊNCIAS","aula":"Os estados da matéria","p":"Um cometa é uma bola de gelo e poeira. Perto do Sol, o gelo dele vira gás direto, sem virar água antes, e forma a cauda. Que mudança é essa?","dica":"Fusão e vaporização passam pelo líquido. Qual mudança pula o líquido e vai do sólido direto para o gás?","porque":"Sublimação: do sólido direto para o gasoso. O gelo-seco faz o mesmo aqui na Terra.","tipo":"opcoes","o":["fusão","vaporização","solidificação","sublimação"],"a":3},{"m":7,"missao":"ASTEROIDES","materia":"CIÊNCIAS","aula":"Os estados da matéria","p":"No alto de uma montanha bem alta, o ar é mais fino. Lá, a água ferve:","dica":"Lembre do feijão que demora mais para cozinhar lá em cima: a água ferve antes de ficar tão quente.","porque":"Com o ar mais fino, a água ferve abaixo de 100 °C. Em La Paz, na Bolívia, a uns 3.600 m de altitude, ela ferve perto de 88 °C.","tipo":"opcoes","o":["acima de 100 °C","exatamente a 100 °C","abaixo de 100 °C","nunca"],"a":2},{"m":7,"missao":"ASTEROIDES","materia":"ASTRONOMIA","aula":"Pedras do começo de tudo","p":"Onde fica o Cinturão de Asteroides?","dica":"Ele fica entre dois planetas: o planeta vermelho e o maior de todos.","porque":"O cinturão fica entre Marte e Júpiter.","tipo":"opcoes","o":["Entre a Terra e a Lua","Depois de Plutão","Entre Marte e Júpiter","Dentro do Sol"],"a":2},{"m":7,"missao":"ASTEROIDES","materia":"ASTRONOMIA","aula":"Pedras do começo de tudo","p":"Uma rocha espacial que cruza o céu e chega até o chão da Terra se chama:","dica":"Procure o nome que a pedra ganha quando já está no chão.","porque":"O pedaço que chega ao chão é um meteorito, como o Bendegó, achado na Bahia.","tipo":"opcoes","o":["cometa","meteorito","satélite","planeta"],"a":1},{"m":7,"missao":"ASTEROIDES","materia":"ASTRONOMIA","aula":"Pedras do começo de tudo","p":"Ceres tem uns 940 km de diâmetro. A Lua tem uns 3.470 km. Quantos km a Lua tem a mais?","dica":"Faça 3.470 − 940. Dica: 3.470 − 1.000 = 2.470, e depois devolva 60.","porque":"3.470 − 940 = 2.530 km. Ceres é o maior do cinturão, mas é bem menor que a nossa Lua.","tipo":"numero","n":2530,"conta":"3.470 − 940 = ?"},{"m":7,"missao":"ASTEROIDES","materia":"ASTRONOMIA","aula":"Pedras do começo de tudo","p":"Na vida real, os asteroides do cinturão:","dica":"Lembre das sondas que atravessam o cinturão sem bater em nada.","porque":"Tem muito espaço vazio entre eles. Os asteroides grudados são coisa de filme.","tipo":"opcoes","o":["ficam grudados uns nos outros","pegam fogo no espaço","não existem de verdade","ficam muito longe uns dos outros"],"a":3},{"m":7,"missao":"ASTEROIDES","materia":"ASTRONOMIA","aula":"Pedras do começo de tudo","p":"Uma rocha vaga no espaço, entra no ar da Terra fazendo um risco de luz, e um pedaço cai no quintal. Na ordem certa, os nomes dela são:","dica":"Primeiro ela está no espaço, depois vira luz no céu, e por último está no chão.","porque":"No espaço é asteroide, o risco de luz é o meteoro, e o pedaço no chão é o meteorito.","tipo":"opcoes","o":["meteoro, asteroide, meteorito","asteroide, meteoro, meteorito","meteorito, meteoro, asteroide","asteroide, meteorito, meteoro"],"a":1},{"m":7,"missao":"ASTEROIDES","materia":"GEOGRAFIA · JAPÃO","aula":"A terra do sol nascente","p":"\"Arigatō\" quer dizer:","dica":"É a palavra que a gente diz depois de ganhar um presente.","porque":"Arigatō = obrigado. Olá é konnichiwa, e estrela é hoshi.","tipo":"opcoes","o":["olá","obrigado","estrela","tchau"],"a":1},{"m":7,"missao":"ASTEROIDES","materia":"GEOGRAFIA · JAPÃO","aula":"A terra do sol nascente","p":"Qual é a capital do Japão?","dica":"Pequim é da China e Seul é da Coreia do Sul. Tanegashima é a ilha da base de foguetes.","porque":"A capital do Japão é Tóquio.","tipo":"opcoes","o":["Pequim","Seul","Tanegashima","Tóquio"],"a":3},{"m":7,"missao":"ASTEROIDES","materia":"GEOGRAFIA · JAPÃO","aula":"A terra do sol nascente","p":"Por que o Japão é chamado de \"Terra do Sol Nascente\"?","dica":"O Sol nasce de qual lado? E o Japão fica de qual lado da Ásia?","porque":"O Sol nasce no leste, e o Japão fica no extremo leste da Ásia.","tipo":"opcoes","o":["Porque fica bem a leste da Ásia, do lado onde o Sol nasce","Porque é um país muito quente","Porque tem muitos vulcões","Porque lá não tem noite"],"a":0},{"m":7,"missao":"ASTEROIDES","materia":"GEOGRAFIA · JAPÃO","aula":"A terra do sol nascente","p":"Tóquio está 12 horas à frente de Brasília. Quando são 8 horas da manhã em Brasília, que horas são em Tóquio? Use o relógio de 24 horas.","dica":"Estar à frente quer dizer que lá o relógio já andou mais. Some 12 horas.","porque":"8 + 12 = 20 horas, ou seja, 8 da noite em Tóquio.","tipo":"numero","n":20,"conta":"8 + 12 = ?"},{"m":7,"missao":"ASTEROIDES","materia":"GEOGRAFIA · JAPÃO","aula":"A terra do sol nascente","p":"Por que o Japão tem tantos terremotos e vulcões?","dica":"Pense no que faz o chão tremer: os pedaços da casca da Terra se mexendo.","porque":"O Japão fica onde placas tectônicas se encontram. Quando elas se mexem, vêm terremotos, e por ali o magma sobe e forma vulcões.","tipo":"opcoes","o":["Porque fica perto do Polo Norte","Porque tem muitas cidades grandes","Porque fica no encontro de placas tectônicas, no Anel de Fogo do Pacífico","Porque fica em cima da Linha do Equador"],"a":2},{"m":8,"missao":"JÚPITER","materia":"MATEMÁTICA","aula":"Equações do 1º grau","p":"Em 2023, Júpiter tinha 95 luas conhecidas. Galileu viu 4 delas em 1610. Quantas foram descobertas depois? Resolva x + 4 = 95.","dica":"Tire 4 dos dois pratos: 95 − 4.","porque":"x = 95 − 4 = 91 luas. Confere: 91 + 4 = 95.","tipo":"numero","n":91,"conta":"x + 4 = 95"},{"m":8,"missao":"JÚPITER","materia":"MATEMÁTICA","aula":"Equações do 1º grau","p":"Um dia em Júpiter dura cerca de 10 horas. Quantos dias de Júpiter cabem em 120 horas? Resolva 10x = 120.","dica":"O 10 está multiplicando. Divida os dois lados por 10.","porque":"x = 120 ÷ 10 = 12 dias de Júpiter. Confere: 10 × 12 = 120.","tipo":"numero","n":12,"conta":"10x = 120"},{"m":8,"missao":"JÚPITER","materia":"MATEMÁTICA","aula":"Equações do 1º grau","p":"O Kdok já registrou 7 luas no Cosmodex e registra 8 por hora. Em quantas horas ele chega às 95? Resolva 8x + 7 = 95.","dica":"Primeiro tire 7 dos dois lados: 95 − 7 = 88. Depois divida por 8.","porque":"8x = 88, então x = 88 ÷ 8 = 11 horas. Confere: 8 × 11 + 7 = 95.","tipo":"numero","n":11,"conta":"8x + 7 = 95"},{"m":8,"missao":"JÚPITER","materia":"MATEMÁTICA","aula":"Equações do 1º grau","p":"Na equação 4x + 6 = 30, qual é o primeiro passo para achar o x?","dica":"O 6 está somando no prato do x. Para ele sumir, faça o contrário de somar, nos dois pratos.","porque":"Tirando 6 dos dois lados fica 4x = 24. Depois, dividindo por 4, x = 6.","tipo":"opcoes","o":["Dividir só o 30 por 4","Somar 6 nos dois lados","Tirar 4 dos dois lados","Tirar 6 dos dois lados"],"a":3},{"m":8,"missao":"JÚPITER","materia":"MATEMÁTICA","aula":"Equações do 1º grau","p":"O Kdok ficou ligado por 54 horas: x dias de Júpiter (10 horas cada) e mais 4 horas. Monte a equação e descubra quantos dias de Júpiter foram.","dica":"Cada dia de Júpiter tem 10 h: 10x + 4 = 54. Tire o 4 dos dois lados e divida por 10.","porque":"10x + 4 = 54 → 10x = 50 → x = 5 dias de Júpiter. Confere: 10 × 5 + 4 = 54.","tipo":"numero","n":5,"conta":null},{"m":8,"missao":"JÚPITER","materia":"MATEMÁTICA","aula":"Equações do 1º grau","p":"A Lia resolveu 6x − 8 = 40 e achou x = 7. Confira: ela acertou?","dica":"Troque o x por 7: 6 × 7 − 8 dá 40? Se não der, resolva: 6x = 40 + 8.","porque":"6 × 7 − 8 = 34, não 40. O certo: 6x = 48, x = 8. Confere: 6 × 8 − 8 = 40.","tipo":"opcoes","o":["Sim: 6 × 7 − 8 = 40","Não: o certo é x = 6","Não: 6 × 7 − 8 dá 34. O certo é x = 8","Não dá para conferir"],"a":2},{"m":8,"missao":"JÚPITER","materia":"ASTRONOMIA","aula":"O rei dos planetas","p":"Júpiter é:","dica":"Lembre quantas Terras caberiam dentro dele.","porque":"Júpiter é o maior planeta: caberiam umas 1.300 Terras dentro dele.","tipo":"opcoes","o":["o menor planeta","uma estrela","o maior planeta do Sistema Solar","uma lua de Saturno"],"a":2},{"m":8,"missao":"JÚPITER","materia":"ASTRONOMIA","aula":"O rei dos planetas","p":"Qual lua de Júpiter é a mais famosa por ter um oceano escondido embaixo do gelo, onde os cientistas procuram vida?","dica":"Io tem vulcões, Ganimedes é a maior e Calisto tem crateras.","porque":"Europa tem um oceano embaixo do gelo. Talvez um dia a gente encontre vida lá.","tipo":"opcoes","o":["Io","Europa","Ganimedes","Calisto"],"a":1},{"m":8,"missao":"JÚPITER","materia":"ASTRONOMIA","aula":"O rei dos planetas","p":"A Grande Mancha Vermelha de Júpiter é:","dica":"Júpiter é feito de gás e não tem chão. O que pode girar sem parar nas nuvens dele?","porque":"É uma tempestade gigante, maior que a Terra, observada há quase 200 anos.","tipo":"opcoes","o":["um vulcão","um lago de lava","uma cidade","uma tempestade maior que a Terra"],"a":3},{"m":8,"missao":"JÚPITER","materia":"ASTRONOMIA","aula":"O rei dos planetas","p":"Júpiter gira em cerca de 10 horas. Quantos dias COMPLETOS de Júpiter cabem em 1 dia da Terra (24 horas)?","dica":"Quantas vezes 10 horas cabem em 24 sem passar? 10 × 2 = 20 e 10 × 3 = 30.","porque":"10 × 2 = 20 cabe em 24, mas 10 × 3 = 30 passa. São 2 dias completos de Júpiter, e sobram 4 horas.","tipo":"numero","n":2,"conta":"24 ÷ 10 = ?"},{"m":8,"missao":"JÚPITER","materia":"ASTRONOMIA","aula":"O rei dos planetas","p":"Por que foi tão importante Galileu ver 4 luas girando em volta de Júpiter, em 1610?","dica":"Naquela época, muita gente achava que tudo no céu girava em volta de um lugar só. Que lugar?","porque":"As luas giravam em volta de Júpiter, e não da Terra. Isso mostrou que a Terra não é o centro de tudo.","tipo":"opcoes","o":["Mostrou que nem tudo no céu gira em volta da Terra","Mostrou que Júpiter é uma estrela","Mostrou que Júpiter tem chão","Mostrou que a Lua é maior que Júpiter"],"a":0},{"m":8,"missao":"JÚPITER","materia":"GEOGRAFIA · GUIANA FRANCESA","aula":"A França na América do Sul","p":"A Guiana Francesa é um território de qual país?","dica":"O nome já dá uma pista. E lá se fala francês.","porque":"É um território da França, mesmo ficando na América do Sul: um departamento ultramarino.","tipo":"opcoes","o":["Brasil","Suriname","França","Portugal"],"a":2},{"m":8,"missao":"JÚPITER","materia":"GEOGRAFIA · GUIANA FRANCESA","aula":"A França na América do Sul","p":"\"Merci\" quer dizer:","dica":"Bom dia é bonjour, e estrela é étoile.","porque":"Merci = obrigado.","tipo":"opcoes","o":["obrigado","bom dia","estrela","tchau"],"a":0},{"m":8,"missao":"JÚPITER","materia":"GEOGRAFIA · GUIANA FRANCESA","aula":"A França na América do Sul","p":"O rio Oiapoque separa o Brasil da Guiana Francesa, e o Chuí fica no extremo sul do Brasil. O que quer dizer \"do Oiapoque ao Chuí\"?","dica":"Um fica lá no norte e o outro lá no sul.","porque":"O Oiapoque fica no norte e o Chuí no sul: a expressão quer dizer o Brasil inteiro.","tipo":"opcoes","o":["Do mar à montanha","Da manhã à noite","De Júpiter a Saturno","De uma ponta à outra do Brasil"],"a":3},{"m":8,"missao":"JÚPITER","materia":"GEOGRAFIA · GUIANA FRANCESA","aula":"A França na América do Sul","p":"A sonda JUICE saiu de Kourou em 2023 e deve chegar a Júpiter em 2031. Quantos anos de viagem?","dica":"Faça 2031 − 2023. Pode contar nos dedos a partir de 2023.","porque":"2031 − 2023 = 8 anos de viagem!","tipo":"numero","n":8,"conta":"2031 − 2023 = ?"},{"m":8,"missao":"JÚPITER","materia":"GEOGRAFIA · GUIANA FRANCESA","aula":"A França na América do Sul","p":"Por que a Europa lança foguetes da Guiana Francesa, tão longe da França?","dica":"Kourou fica perto de uma linha imaginária muito famosa. O que acontece ali com o giro da Terra?","porque":"Perto do Equador, o chão gira mais rápido. O foguete já sai com esse empurrão e gasta menos combustível.","tipo":"opcoes","o":["Porque lá é mais frio","Porque perto do Equador a Terra gira mais rápido e dá um empurrão extra no foguete","Porque lá não tem vento","Porque fica mais perto da Lua"],"a":1},{"m":9,"missao":"SATURNO","materia":"GEOGRAFIA","aula":"Onde fica cada lugar","p":"O Sol nasce, mais ou menos, de qual lado?","dica":"É o mesmo lado que dá o apelido ao Japão: a Terra do Sol Nascente.","porque":"O Sol nasce do lado leste e se põe do lado oeste.","tipo":"opcoes","o":["oeste","norte","leste","sul"],"a":2},{"m":9,"missao":"SATURNO","materia":"GEOGRAFIA","aula":"Onde fica cada lugar","p":"Qual linha imaginária divide a Terra em Hemisfério Norte e Hemisfério Sul?","dica":"É a linha de 0° de latitude, que passa bem no meio do planeta.","porque":"A Linha do Equador divide a Terra em norte e sul. Greenwich divide em leste e oeste.","tipo":"opcoes","o":["Linha do Equador","Meridiano de Greenwich","Trópico de Câncer","Trópico de Capricórnio"],"a":0},{"m":9,"missao":"SATURNO","materia":"GEOGRAFIA","aula":"Onde fica cada lugar","p":"De manhã, no pátio, JACI apontou o braço direito para onde o Sol nasceu. Para que lado JACI está de frente?","dica":"O braço direito aponta o leste. Use o truque da aula.","porque":"Com o braço direito no leste, a frente fica no norte, as costas no sul e o braço esquerdo no oeste.","tipo":"opcoes","o":["sul","norte","oeste","leste"],"a":1},{"m":9,"missao":"SATURNO","materia":"GEOGRAFIA","aula":"Onde fica cada lugar","p":"O Trópico de Câncer fica a cerca de 23° ao norte do Equador, e o de Capricórnio, a 23° ao sul. Quantos graus de latitude separam os dois trópicos?","dica":"Um está ao norte e o outro ao sul. Do primeiro até o Equador são 23°, e do Equador até o segundo, mais 23°.","porque":"23 + 23 = 46°. Essa faixa entre os dois é a zona tropical.","tipo":"numero","n":46,"conta":"23 + 23 = ?"},{"m":9,"missao":"SATURNO","materia":"GEOGRAFIA","aula":"Onde fica cada lugar","p":"O Vale do Capão fica a cerca de 13° S e 41° O. Qual destas frases está certa?","dica":"S quer dizer sul e O quer dizer oeste. E 13° está entre 0° (Equador) e 23° (Trópico de Capricórnio).","porque":"13° S é Hemisfério Sul, 41° O é a oeste de Greenwich, e 13° fica entre o Equador e o Trópico de Capricórnio.","tipo":"opcoes","o":["O Capão fica no Hemisfério Norte, a leste de Greenwich","O Capão fica ao norte do Trópico de Câncer","O Capão fica em cima da Linha do Equador","O Capão fica no Hemisfério Sul, a oeste de Greenwich, entre o Equador e o Trópico de Capricórnio"],"a":3},{"m":9,"missao":"SATURNO","materia":"GEOGRAFIA","aula":"Onde fica cada lugar","p":"Baikonur fica a cerca de 46° N, e o Capão, a cerca de 13° S. Quantos graus de latitude separam os dois lugares?","dica":"Um está no norte e o outro no sul: o caminho passa pelo Equador. Some a distância de cada um até o Equador.","porque":"De Baikonur até o Equador são 46°, e do Equador até o Capão, mais 13°: 46 + 13 = 59°.","tipo":"numero","n":59,"conta":"46 + 13 = ?"},{"m":9,"missao":"SATURNO","materia":"ASTRONOMIA","aula":"O senhor dos anéis","p":"Do que são feitos os anéis de Saturno?","dica":"São bilhões de pedacinhos, de grãos até blocos do tamanho de uma casa.","porque":"Os anéis são bilhões de pedaços de gelo e rocha girando em volta do planeta.","tipo":"opcoes","o":["ouro","fumaça","pedaços de gelo e rocha","arco-íris"],"a":2},{"m":9,"missao":"SATURNO","materia":"ASTRONOMIA","aula":"O senhor dos anéis","p":"Titã, a maior lua de Saturno, tem:","dica":"Lá faz um frio enorme. Os lagos não são de água.","porque":"Titã tem rios e lagos de metano líquido.","tipo":"opcoes","o":["florestas","lagos de metano líquido","cidades","oceanos de lava"],"a":1},{"m":9,"missao":"SATURNO","materia":"ASTRONOMIA","aula":"O senhor dos anéis","p":"Se existisse uma banheira gigante cheia de água, maior que Saturno, o planeta:","dica":"Saturno é muito pouco denso: é mais leve que a mesma quantidade de água.","porque":"Saturno é menos denso que a água, então boiaria.","tipo":"opcoes","o":["afundaria rápido","derreteria","voaria para longe","boiaria"],"a":3},{"m":9,"missao":"SATURNO","materia":"ASTRONOMIA","aula":"O senhor dos anéis","p":"Saturno leva uns 29 anos para dar a volta no Sol. Quantas voltas ele dá em 87 anos?","dica":"Quantas vezes 29 cabe em 87? Experimente 29 + 29 + 29.","porque":"29 × 3 = 87, então são 3 voltas.","tipo":"numero","n":3,"conta":"87 ÷ 29 = ?"},{"m":9,"missao":"SATURNO","materia":"ASTRONOMIA","aula":"O senhor dos anéis","p":"Em março de 2025, a Terra ficou alinhada com os anéis de Saturno e a gente os viu bem de lado. O que aconteceu?","dica":"Os anéis são largos, mas têm só uns 10 metros de espessura em muitos lugares. Como fica uma folha de papel vista de lado?","porque":"Vistos de lado, os anéis viram uma linha fininha e quase somem no telescópio.","tipo":"opcoes","o":["Ficaram mais brilhantes","Viraram um círculo completo","Quase sumiram, porque são finíssimos","Mudaram de cor"],"a":2},{"m":9,"missao":"SATURNO","materia":"HISTÓRIA · CAZAQUISTÃO","aula":"Onde a corrida espacial começou","p":"Quem foi o primeiro ser humano no espaço, em 1961?","dica":"Foi um cosmonauta que saiu de Baikonur e gritou \"Poyekhali!\".","porque":"Yuri Gagarin, saindo de Baikonur. Neil Armstrong foi o primeiro a pisar na Lua, em 1969.","tipo":"opcoes","o":["Neil Armstrong","Yuri Gagarin","Marcos Pontes","Galileu"],"a":1},{"m":9,"missao":"SATURNO","materia":"HISTÓRIA · CAZAQUISTÃO","aula":"Onde a corrida espacial começou","p":"Na decolagem, Gagarin gritou \"Poyekhali!\". O que isso quer dizer?","dica":"Releia a tela 3: é o que Gagarin gritou quando a viagem ia começar.","porque":"Poyekhali quer dizer \"Vamos!\".","tipo":"opcoes","o":["\"Houston, temos um problema\"","\"Olá, Lua!\"","\"Vamos!\"","\"Cadê meu lanche?\""],"a":2},{"m":9,"missao":"SATURNO","materia":"HISTÓRIA · CAZAQUISTÃO","aula":"Onde a corrida espacial começou","p":"O Sputnik subiu em 1957 e Gagarin em 1961. Quantos anos de diferença?","dica":"Faça 1961 − 1957, ou conte nos dedos a partir de 1957.","porque":"1961 − 1957 = 4 anos.","tipo":"numero","n":4,"conta":"1961 − 1957 = ?"},{"m":9,"missao":"SATURNO","materia":"HISTÓRIA · CAZAQUISTÃO","aula":"Onde a corrida espacial começou","p":"O Cazaquistão é o maior país do mundo que:","dica":"Ele fica no meio da Ásia, todo cercado de terra.","porque":"É o maior país sem saída para o mar: todo cercado de terra.","tipo":"opcoes","o":["tem mais praias","tem mais vulcões","fica na América","não tem saída para o mar"],"a":3},{"m":9,"missao":"SATURNO","materia":"HISTÓRIA · CAZAQUISTÃO","aula":"Onde a corrida espacial começou","p":"Quando o Sputnik e Gagarin partiram de Baikonur, o Cazaquistão fazia parte de qual país?","dica":"Era o país que disputava a corrida espacial com os Estados Unidos, e que acabou em 1991.","porque":"O Cazaquistão fez parte da União Soviética até 1991. Foi ela que construiu Baikonur.","tipo":"opcoes","o":["União Soviética","Estados Unidos","Japão","China"],"a":0},{"m":10,"missao":"URANO","materia":"MATEMÁTICA","aula":"Potências e raízes","p":"Um bloco de gelo se parte em 2 pedaços. Cada pedaço se parte em 2 de novo, e isso acontece 4 vezes seguidas. Quantos pedaços ficam no fim? Calcule 2⁴.","dica":"Vá dobrando: 2, depois 4, depois 8... até multiplicar por 2 quatro vezes.","porque":"2⁴ = 2 × 2 × 2 × 2 = 16 pedaços.","tipo":"numero","n":16,"conta":"2 × 2 × 2 × 2 = ?"},{"m":10,"missao":"URANO","materia":"MATEMÁTICA","aula":"Potências e raízes","p":"Quanto é 5²?","dica":"Ao quadrado quer dizer o número vezes ele mesmo. Não é 5 × 2.","porque":"5² = 5 × 5 = 25. O expoente 2 manda repetir o 5 duas vezes.","tipo":"opcoes","o":["10","25","7","52"],"a":1},{"m":10,"missao":"URANO","materia":"MATEMÁTICA","aula":"Potências e raízes","p":"A sala de amostras da nave é um quadrado com 64 m² de área. Quanto mede cada lado, em metros? (É a raiz quadrada de 64.)","dica":"Qual número vezes ele mesmo dá 64? Teste 7 × 7 e 8 × 8.","porque":"8 × 8 = 64, então √64 = 8. Cada lado mede 8 m.","tipo":"numero","n":8,"conta":"√64 = ?"},{"m":10,"missao":"URANO","materia":"MATEMÁTICA","aula":"Potências e raízes","p":"Para sair da Terra, a nave gasta 3 × 10⁴ litros de combustível. Quantos litros é isso?","dica":"10⁴ é 1 seguido de 4 zeros: 10.000. Agora multiplique por 3.","porque":"10⁴ = 10.000, e 3 × 10.000 = 30.000 litros.","tipo":"numero","n":30000,"conta":"3 × 10⁴ = ?"},{"m":10,"missao":"URANO","materia":"MATEMÁTICA","aula":"Potências e raízes","p":"JACI ficou na dúvida e perguntou se 2³ e 3² dão o mesmo resultado. Qual é a resposta certa?","dica":"2³ = 2 × 2 × 2. 3² = 3 × 3. Faça as duas contas antes de responder.","porque":"2³ = 8 e 3² = 9. Trocar a base pelo expoente muda o resultado. Quem achou 6 e 6 multiplicou a base pelo expoente, que é o erro comum.","tipo":"opcoes","o":["Sim: 2³ = 6 e 3² = 6","Não: 2³ = 9 e 3² = 8","Não: 2³ = 8 e 3² = 9"],"a":2},{"m":10,"missao":"URANO","materia":"MATEMÁTICA","aula":"Potências e raízes","p":"Um milhão é 10⁶ e um bilhão é 10⁹. Um bilhão é quantas vezes um milhão?","dica":"Um bilhão tem 9 zeros e um milhão tem 6. Corte 6 zeros dos dois: quantos zeros sobram no bilhão?","porque":"9 − 6 = 3 zeros sobram: 10³ = 1.000. Um bilhão são mil milhões.","tipo":"numero","n":1000,"conta":"1 bilhão ÷ 1 milhão = ?"},{"m":10,"missao":"URANO","materia":"ASTRONOMIA","aula":"O gigante deitado","p":"Urano tem um jeito muito estranho de girar. Qual é?","dica":"Lembre da tela 2: Urano parece uma bola rolando pelo caminho em volta do Sol.","porque":"Urano gira deitado, com o eixo quase na horizontal. Os cientistas acham que uma batida enorme, há muito tempo, o derrubou de lado.","tipo":"opcoes","o":["Ele nunca gira","Ele é quadrado e rola aos pulos","Ele gira deitado, de lado"],"a":2},{"m":10,"missao":"URANO","materia":"ASTRONOMIA","aula":"O gigante deitado","p":"Urano foi o primeiro planeta descoberto com telescópio, em 1781. Quem o descobriu?","dica":"Foi um astrônomo que morava na Inglaterra e construía os próprios telescópios.","porque":"William Herschel achou Urano em 1781 e, no começo, pensou que fosse um cometa. Galileu viveu bem antes, e Newton ficou famoso estudando a gravidade.","tipo":"opcoes","o":["Galileu Galilei","William Herschel","Isaac Newton"],"a":1},{"m":10,"missao":"URANO","materia":"ASTRONOMIA","aula":"O gigante deitado","p":"Urano leva 84 anos para dar uma volta no Sol. Em cada polo, metade desse tempo é de dia sem parar e a outra metade é de noite sem parar. Quantos anos dura a noite no polo?","dica":"O ano de Urano tem 84 anos da Terra. A noite do polo é a metade disso.","porque":"84 ÷ 2 = 42. No polo de Urano, são cerca de 42 anos de dia seguidos e 42 anos de noite seguidos.","tipo":"numero","n":42,"conta":"84 ÷ 2 = ?"},{"m":10,"missao":"URANO","materia":"ASTRONOMIA","aula":"O gigante deitado","p":"Por que Urano tem cor azul-esverdeada?","dica":"Volte à tela 3: um gás no ar de Urano segura a luz vermelha e deixa voltar o azul.","porque":"O metano absorve a luz vermelha do Sol. O que volta para os nossos olhos é o azul-esverdeado. Urano não tem oceanos nem florestas.","tipo":"opcoes","o":["Por causa do gás metano da atmosfera","Por causa de oceanos de água","Por causa de florestas geladas"],"a":0},{"m":10,"missao":"URANO","materia":"ASTRONOMIA","aula":"O gigante deitado","p":"Urano foi descoberto em 1781, e a Voyager 2 passou por ele em 1986. Nesse tempo, quantas voltas COMPLETAS Urano deu em volta do Sol? Cada volta leva 84 anos.","dica":"Primeiro ache quantos anos passaram: 1986 − 1781. Depois teste 84 × 2 e 84 × 3.","porque":"1986 − 1781 = 205 anos. 84 × 2 = 168 cabe em 205, mas 84 × 3 = 252 passa. Foram 2 voltas completas.","tipo":"numero","n":2,"conta":"1986 − 1781 = ? quantos 84 cabem?"},{"m":10,"missao":"URANO","materia":"GEOGRAFIA · REINO UNIDO","aula":"Onde começam as horas","p":"Qual é a capital do Reino Unido?","dica":"É a cidade cortada pelo rio Tâmisa, onde fica Greenwich.","porque":"Londres é a capital do Reino Unido. Paris é a capital da França, e Dublin, da Irlanda.","tipo":"opcoes","o":["Paris","Londres","Dublin"],"a":1},{"m":10,"missao":"URANO","materia":"GEOGRAFIA · REINO UNIDO","aula":"Onde começam as horas","p":"O Meridiano de Greenwich marca a longitude:","dica":"Greenwich é o ponto de partida das longitudes. Por qual número começa uma contagem?","porque":"O Meridiano de Greenwich é a longitude 0°. A partir dele se contam os graus para leste e para oeste.","tipo":"opcoes","o":["90°","180°","0°"],"a":2},{"m":10,"missao":"URANO","materia":"GEOGRAFIA · REINO UNIDO","aula":"Onde começam as horas","p":"É meio-dia (12 h) em Londres, no inverno de lá. Brasília está 3 horas atrás. Que horas são em Brasília?","dica":"Brasília fica a oeste, então o relógio daqui está atrasado: tire 3 de 12.","porque":"12 − 3 = 9. São 9 h da manhã em Brasília.","tipo":"numero","n":9,"conta":"12 − 3 = ?"},{"m":10,"missao":"URANO","materia":"GEOGRAFIA · REINO UNIDO","aula":"Onde começam as horas","p":"A Terra gira 360 graus em 24 horas. Quantos graus ela gira em 1 hora? Essa é a largura de cada fuso horário.","dica":"24 × 10 = 240 e 24 × 5 = 120. Juntando, 240 + 120 = 360. Quanto é 10 + 5?","porque":"360 ÷ 24 = 15. Cada fuso horário tem 15 graus de largura.","tipo":"numero","n":15,"conta":"360 ÷ 24 = ?"},{"m":10,"missao":"URANO","materia":"GEOGRAFIA · REINO UNIDO","aula":"Onde começam as horas","p":"No verão de Londres, os relógios de lá são adiantados 1 hora, e a diferença para Brasília passa a ser de 4 horas. Em julho, um jogo de futebol começa às 20 h em Londres. Que horas são em Brasília?","dica":"Julho é verão em Londres: use a diferença de 4 horas, não de 3. Brasília continua atrás.","porque":"No verão de lá, a diferença é de 4 horas. 20 − 4 = 16. O jogo começa às 16 h em Brasília.","tipo":"numero","n":16,"conta":"20 − 4 = ?"},{"m":11,"missao":"NETUNO","materia":"PORTUGUÊS","aula":"Concordância verbal e nominal","p":"Complete: \"Os ventos de Netuno ___ a 2.000 km/h.\"","dica":"Pergunte ao verbo: o que chega? Os ventos. É um ou são vários?","porque":"O sujeito é \"os ventos\", no plural. Então o verbo vai para o plural: os ventos chegam.","tipo":"opcoes","o":["chega","chegam","chegou"],"a":1},{"m":11,"missao":"NETUNO","materia":"PORTUGUÊS","aula":"Concordância verbal e nominal","p":"Complete: \"Netuno tem anéis ___.\"","dica":"\"Anéis\" é masculino e está no plural. Os adjetivos precisam combinar com ele.","porque":"Anéis é masculino plural, então os adjetivos também: anéis finos e escuros.","tipo":"opcoes","o":["fino e escuro","finas e escuras","finos e escuros"],"a":2},{"m":11,"missao":"NETUNO","materia":"PORTUGUÊS","aula":"Concordância verbal e nominal","p":"Complete: \"Urano e Netuno ___ gigantes de gelo.\"","dica":"Quantos planetas são o sujeito da frase? Dois sujeitos juntos pedem o verbo no plural.","porque":"O sujeito tem dois planetas, Urano e Netuno. Sujeito composto pede plural: são.","tipo":"opcoes","o":["é","são","era"],"a":1},{"m":11,"missao":"NETUNO","materia":"PORTUGUÊS","aula":"Concordância verbal e nominal","p":"Qual frase está de acordo com a norma-padrão?","dica":"O sujeito está depois do verbo. Pergunte: o que chegou? Depois veja se o verbo combina com a resposta.","porque":"O que chegou? As fotos, no plural. Mesmo vindo depois do verbo, o sujeito manda: chegaram as fotos.","tipo":"opcoes","o":["Chegaram as fotos de Netuno.","Chegou as fotos de Netuno.","Chegaram a foto de Netuno."],"a":0},{"m":11,"missao":"NETUNO","materia":"PORTUGUÊS","aula":"Concordância verbal e nominal","p":"Qual frase está de acordo com a norma-padrão?","dica":"Aqui \"haver\" quer dizer existir. Nesse sentido, ele fica sempre no singular. E o substantivo \"nuvens\" combina com \"brancas\".","porque":"Haver no sentido de existir não vai para o plural: havia. E muitas nuvens brancas, tudo no plural. Netuno tem mesmo nuvens brancas de gelo de metano.","tipo":"opcoes","o":["Haviam muitas nuvens brancas em Netuno.","Havia muitas nuvens brancas em Netuno.","Havia muitas nuvem branca em Netuno."],"a":1},{"m":11,"missao":"NETUNO","materia":"PORTUGUÊS","aula":"Concordância verbal e nominal","p":"Qual frase está de acordo com a norma-padrão?","dica":"\"Menos\" nunca muda. \"Meio\" antes de adjetivo quer dizer \"um pouco\" e não muda. Mas \"meia hora\" é metade de uma hora.","porque":"\"Meio-dia e meia\" está certo: é meio-dia e meia hora. \"Menas\" não existe (é menos), e \"meia cansada\" deveria ser \"meio cansada\", porque ali meio quer dizer um pouco.","tipo":"opcoes","o":["Ontem tinha menas estrelas no céu.","A Dra. Priya ficou meia cansada.","Era meio-dia e meia quando a nave partiu."],"a":2},{"m":11,"missao":"NETUNO","materia":"ASTRONOMIA","aula":"O planeta achado no papel","p":"Como Netuno foi descoberto, em 1846?","dica":"Lembre da tela 1: Urano estava sendo puxado por alguma coisa. O que Le Verrier fez com isso?","porque":"Le Verrier calculou onde o planeta devia estar, e Galle o achou lá. Netuno foi descoberto primeiro no papel. A olho nu ele nem aparece.","tipo":"opcoes","o":["Por acaso, olhando o céu a olho nu","Por cálculos de matemática, antes de ser visto","Uma nave tirou uma foto dele"],"a":1},{"m":11,"missao":"NETUNO","materia":"ASTRONOMIA","aula":"O planeta achado no papel","p":"Qual é o planeta mais distante do Sol?","dica":"Cuidado com Plutão: desde 2006 ele é planeta-anão, não planeta.","porque":"Netuno é o oitavo e o mais distante dos planetas. Plutão costuma ficar mais longe, mas é um planeta-anão.","tipo":"opcoes","o":["Urano","Plutão","Netuno","Saturno"],"a":2},{"m":11,"missao":"NETUNO","materia":"ASTRONOMIA","aula":"O planeta achado no papel","p":"Netuno foi descoberto em 1846 e leva 165 anos para dar uma volta no Sol. Em que ano ele completou a primeira volta desde a descoberta?","dica":"Some o tempo de uma volta ao ano da descoberta.","porque":"1846 + 165 = 2011. Só em 2011 Netuno completou a primeira volta desde que foi descoberto.","tipo":"numero","n":2011,"conta":"1846 + 165 = ?"},{"m":11,"missao":"NETUNO","materia":"ASTRONOMIA","aula":"O planeta achado no papel","p":"Os ventos de Netuno chegam a 2.000 km/h. Um carro na estrada anda a 100 km/h. Quantas vezes o vento é mais rápido que o carro?","dica":"Quantos 100 cabem em 2.000? Corte dois zeros dos dois números.","porque":"2.000 ÷ 100 = 20. O vento de Netuno é 20 vezes mais rápido que o carro.","tipo":"numero","n":20,"conta":"2.000 ÷ 100 = ?"},{"m":11,"missao":"NETUNO","materia":"ASTRONOMIA","aula":"O planeta achado no papel","p":"A luz do Sol leva 8 minutos para chegar à Terra e cerca de 4 horas para chegar a Netuno. Quantas vezes Netuno está mais longe do Sol que a Terra?","dica":"Passe 4 horas para minutos (cada hora tem 60). Depois veja quantas vezes 8 cabe nesse número.","porque":"4 × 60 = 240 minutos, e 240 ÷ 8 = 30. A luz anda sempre na mesma velocidade, então Netuno está cerca de 30 vezes mais longe do Sol que a Terra.","tipo":"numero","n":30,"conta":"4 h = ? min depois ÷ 8"},{"m":11,"missao":"NETUNO","materia":"HISTÓRIA · ÍNDIA","aula":"O país do zero","p":"Qual é a capital da Índia?","dica":"Volte à tela 1. Sriharikota é a ilha da base de foguetes, não a capital.","porque":"A capital da Índia é Nova Délhi. Mumbai é uma cidade enorme do litoral, e Sriharikota é a ilha dos foguetes.","tipo":"opcoes","o":["Mumbai","Sriharikota","Nova Délhi"],"a":2},{"m":11,"missao":"NETUNO","materia":"HISTÓRIA · ÍNDIA","aula":"O país do zero","p":"Os números que usamos (0, 1, 2, 3...) se chamam:","dica":"O nome junta o país onde eles nasceram e o povo que os levou para a Europa.","porque":"Indo-arábicos: nasceram na Índia e chegaram à Europa pelos árabes.","tipo":"opcoes","o":["romanos","indo-arábicos","gregos"],"a":1},{"m":11,"missao":"NETUNO","materia":"HISTÓRIA · ÍNDIA","aula":"O país do zero","p":"Até 1947, a Índia foi dominada por qual país?","dica":"É o país da missão passada, onde fica Greenwich.","porque":"O Reino Unido dominou a Índia por quase 200 anos. A independência veio em 1947.","tipo":"opcoes","o":["Reino Unido","França","Espanha"],"a":0},{"m":11,"missao":"NETUNO","materia":"HISTÓRIA · ÍNDIA","aula":"O país do zero","p":"Como Gandhi liderou a luta pela independência da Índia?","dica":"Lembre da Marcha do Sal: o povo caminhou junto, sem armas.","porque":"Gandhi usou protestos pacíficos, como marchas e greves, sem violência. Essa ideia inspirou lutas pelo mundo todo.","tipo":"opcoes","o":["Com um grande exército","Fugindo para outro país","Com protestos pacíficos, sem armas"],"a":2},{"m":11,"missao":"NETUNO","materia":"HISTÓRIA · ÍNDIA","aula":"O país do zero","p":"Brahmagupta escreveu as regras do zero em 628. A Chandrayaan-3 pousou na Lua em 2023. Quantos anos separam os dois feitos?","dica":"Faça 2023 − 628. Se ajudar: 2028 − 628 = 1.400, e 2023 é 5 a menos que 2028.","porque":"2023 − 628 = 1.395 anos. Do zero no papel até a Lua!","tipo":"numero","n":1395,"conta":"2023 − 628 = ?"},{"m":12,"missao":"PLUTÃO","materia":"MATEMÁTICA","aula":"Média, mediana e moda","p":"Nas três aulas da semana, cadete ganhou 3, 5 e 4 estrelas. Qual foi a média de estrelas por aula?","dica":"Some as três: 3 + 5 + 4. Depois divida por 3, porque são três aulas.","porque":"3 + 5 + 4 = 12 e 12 ÷ 3 = 4 estrelas por aula.","tipo":"numero","n":4,"conta":"(3 + 5 + 4) ÷ 3 = ?"},{"m":12,"missao":"PLUTÃO","materia":"MATEMÁTICA","aula":"Média, mediana e moda","p":"Os tamanhos de tênis de seis colegas: 35, 36, 36, 38, 36, 39. Qual é a moda?","dica":"A moda é o número que aparece mais vezes. Conte quantas vezes aparece cada um.","porque":"O 36 aparece três vezes; os outros, uma vez só. A moda é 36.","tipo":"opcoes","o":["36","38","35","39"],"a":0},{"m":12,"missao":"PLUTÃO","materia":"MATEMÁTICA","aula":"Média, mediana e moda","p":"As alturas de cinco pinguins, em cm: 70, 65, 80, 60, 75. Qual é a mediana?","dica":"Primeiro coloque em ordem: 60, 65, 70, 75, 80. A mediana é o valor que fica no meio.","porque":"Em ordem: 60, 65, 70, 75, 80. O do meio é 70 cm. O 80 estava no meio da lista bagunçada, mas a mediana só vale depois de pôr em ordem.","tipo":"numero","n":70,"conta":"70 65 80 60 75"},{"m":12,"missao":"PLUTÃO","materia":"MATEMÁTICA","aula":"Média, mediana e moda","p":"Quatro astronautas têm 30, 42, 36 e 48 anos. Qual é a mediana das idades?","dica":"Coloque em ordem: 30, 36, 42, 48. São quatro números, então sobram dois no meio. A mediana é a média desses dois.","porque":"Em ordem: 30, 36, 42, 48. No meio ficam 36 e 42: (36 + 42) ÷ 2 = 78 ÷ 2 = 39 anos.","tipo":"opcoes","o":["36 anos","42 anos","39 anos","78 anos"],"a":2},{"m":12,"missao":"PLUTÃO","materia":"MATEMÁTICA","aula":"Média, mediana e moda","p":"cadete tirou 6 e 7 nas duas primeiras provas. Quanto precisa tirar na terceira para fechar o bimestre com média 7?","dica":"Média 7 em três provas quer dizer 7 × 3 = 21 pontos no total. Quanto já tem com 6 + 7? O que falta é a nota da terceira prova.","porque":"7 × 3 = 21 pontos no total. Já tem 6 + 7 = 13. Falta 21 − 13 = 8.","tipo":"numero","n":8,"conta":"7 × 3 = ? depois − (6 + 7)"},{"m":12,"missao":"PLUTÃO","materia":"MATEMÁTICA","aula":"Média, mediana e moda","p":"Numa mesa estão quatro crianças e o pai de uma delas: 12, 13, 12, 14 e 49 anos. Quanto a média é MAIOR que a mediana?","dica":"Média: some os cinco (dá 100) e divida por 5. Mediana: coloque em ordem e pegue o do meio. Depois tire a mediana da média.","porque":"Média: 100 ÷ 5 = 20. Em ordem: 12, 12, 13, 14, 49, mediana 13. 20 − 13 = 7. O 49 puxou a média para cima; a mediana nem se mexeu.","tipo":"numero","n":7,"conta":"média − mediana = ?"},{"m":12,"missao":"PLUTÃO","materia":"ASTRONOMIA","aula":"O pequeno valente","p":"Desde 2006, Plutão é chamado de:","dica":"Lembre da tela 1: em 2006, Plutão ganhou uma classificação nova por ser pequeno.","porque":"Desde 2006, Plutão é um planeta-anão. Ele continua lá, girando em volta do Sol, mas não é mais contado como planeta.","tipo":"opcoes","o":["estrela","planeta-anão","cometa"],"a":1},{"m":12,"missao":"PLUTÃO","materia":"ASTRONOMIA","aula":"O pequeno valente","p":"Em 2015, a New Horizons fotografou em Plutão uma planície com formato de coração. Ela é feita de:","dica":"Lá faz cerca de −230 °C. O que existe num lugar tão frio?","porque":"É uma planície de gelo. Com −230 °C, não dá para ter lava quente na superfície.","tipo":"opcoes","o":["lava quente","areia","gelo"],"a":2},{"m":12,"missao":"PLUTÃO","materia":"ASTRONOMIA","aula":"O pequeno valente","p":"Plutão foi descoberto em 1930 e fotografado de perto em 2015. Quantos anos depois?","dica":"Tire o ano da descoberta do ano das fotos: 2015 − 1930.","porque":"2015 − 1930 = 85 anos entre a descoberta e as primeiras fotos de perto.","tipo":"numero","n":85,"conta":"2015 − 1930 = ?"},{"m":12,"missao":"PLUTÃO","materia":"ASTRONOMIA","aula":"O pequeno valente","p":"Por que Plutão deixou de ser chamado de planeta?","dica":"Plutão continua lá, girando em volta do Sol. O que mudou foi a classificação. Releia a tela 1.","porque":"Plutão é menor que a Lua e não domina o próprio caminho: há muitos corpos gelados perto dele. Por isso, desde 2006, é planeta-anão.","tipo":"opcoes","o":["Porque é pequeno e divide o caminho em volta do Sol com muitos outros corpos gelados","Porque ele explodiu em 2006","Porque saiu do Sistema Solar"],"a":0},{"m":12,"missao":"PLUTÃO","materia":"ASTRONOMIA","aula":"O pequeno valente","p":"Plutão foi descoberto em 1930 e leva 248 anos para dar uma volta no Sol. Em que ano ele vai completar a primeira volta inteira desde a descoberta?","dica":"Some 248 ao ano da descoberta. Comece por 1930 + 200 = 2130 e depois some 48.","porque":"1930 + 248 = 2178. Ninguém que viu a descoberta vai ver essa volta terminar!","tipo":"numero","n":2178,"conta":"1930 + 248 = ?"},{"m":12,"missao":"PLUTÃO","materia":"GEOGRAFIA · ANTÁRTIDA","aula":"O continente de gelo","p":"A Antártida é:","dica":"Lembre da tela 1: ela é maior que o Brasil e fica no Polo Sul.","porque":"A Antártida é um continente inteiro, quase todo coberto de gelo.","tipo":"opcoes","o":["um país","um continente coberto de gelo","uma ilha do Brasil"],"a":1},{"m":12,"missao":"PLUTÃO","materia":"GEOGRAFIA · ANTÁRTIDA","aula":"O continente de gelo","p":"Qual destes animais vive na Antártida?","dica":"Os ursos-polares vivem no outro polo, o Norte.","porque":"Pinguins vivem na Antártida. Ursos-polares vivem no Ártico, perto do Polo Norte.","tipo":"opcoes","o":["pinguim","urso-polar","onça"],"a":0},{"m":12,"missao":"PLUTÃO","materia":"GEOGRAFIA · ANTÁRTIDA","aula":"O continente de gelo","p":"De quem é a Antártida?","dica":"Lembre do acordo de 1959, o Tratado da Antártida.","porque":"Pelo Tratado da Antártida, de 1959, nenhum país pode tomar a Antártida para si. Lá vale a pesquisa e a paz, e o Brasil participa com a Estação Comandante Ferraz.","tipo":"opcoes","o":["Do Brasil","Dos Estados Unidos","De nenhum país: um tratado a reserva para a paz e a ciência"],"a":2},{"m":12,"missao":"PLUTÃO","materia":"GEOGRAFIA · ANTÁRTIDA","aula":"O continente de gelo","p":"A Estação Comandante Ferraz foi inaugurada em 1984. Um incêndio destruiu a estação antiga em 2012. Quantos anos ela funcionou?","dica":"Tire o ano da inauguração do ano do incêndio: 2012 − 1984.","porque":"2012 − 1984 = 28 anos. A estação nova ficou pronta em 2020.","tipo":"numero","n":28,"conta":"2012 − 1984 = ?"},{"m":12,"missao":"PLUTÃO","materia":"GEOGRAFIA · ANTÁRTIDA","aula":"O continente de gelo","p":"O recorde de frio da Antártida é −89 °C, e o de calor, cerca de 18 °C. Quantos graus separam essas duas temperaturas?","dica":"De −89 até 0 são 89 graus. De 0 até 18, mais 18. Some os dois pedaços.","porque":"89 + 18 = 107 graus. É o mesmo que 18 − (−89) = 18 + 89 = 107.","tipo":"numero","n":107,"conta":"18 − (−89) = ?"},{"m":13,"missao":"PRÓXIMA CENTAURI","materia":"HISTÓRIA","aula":"A linha do tempo","p":"A Independência do Brasil foi em 1822. Esse ano fica em qual século?","dica":"Tire os dois últimos algarismos (18) e some 1. Depois escreva em romano: X = 10, V = 5, I = 1.","porque":"18 + 1 = 19, século XIX: os anos de 1801 a 1900.","tipo":"opcoes","o":["século XVIII","século XIX","século XX","século XXI"],"a":1},{"m":13,"missao":"PRÓXIMA CENTAURI","materia":"HISTÓRIA","aula":"A linha do tempo","p":"Qual é a ordem certa dos períodos da história do Brasil, do mais antigo para o mais novo?","dica":"Primeiro o Brasil era de Portugal. Depois teve imperador. Hoje tem presidente.","porque":"Colônia (1500 a 1822), Império (1822 a 1889) e República (de 1889 até hoje).","tipo":"opcoes","o":["Colônia, Império, República","República, Colônia, Império","Império, Colônia, República"],"a":0},{"m":13,"missao":"PRÓXIMA CENTAURI","materia":"HISTÓRIA","aula":"A linha do tempo","p":"O Império começou com a Independência, em 1822, e acabou com a Proclamação da República, em 1889. Quantos anos durou o Império?","dica":"Para saber quanto tempo passou entre dois anos, tire o menor do maior: 1889 − 1822.","porque":"1889 − 1822 = 67 anos de Império.","tipo":"numero","n":67,"conta":"1889 − 1822 = ?"},{"m":13,"missao":"PRÓXIMA CENTAURI","materia":"HISTÓRIA","aula":"A linha do tempo","p":"As grandes pirâmides do Egito foram feitas por volta de 2500 a.C. Por volta de 250 a.C., o grego Aristarco disse que a Terra gira em volta do Sol. Quantos anos separam os dois fatos?","dica":"Os dois anos são a.C., então se conta para trás. A distância entre eles é o maior menos o menor.","porque":"2500 − 250 = 2250 anos. As pirâmides são mais antigas, porque em a.C. o número maior vem antes.","tipo":"numero","n":2250,"conta":"2500 − 250 = ?"},{"m":13,"missao":"PRÓXIMA CENTAURI","materia":"HISTÓRIA","aula":"A linha do tempo","p":"Salvador foi a primeira capital do Brasil, de 1549 até 1763, quando a capital passou para o Rio de Janeiro. Por quantos anos Salvador foi a capital?","dica":"Tire o ano do começo do ano do fim: 1763 − 1549. Faça por partes: 1763 − 1500 e depois tire 49.","porque":"1763 − 1549 = 214 anos. Salvador foi a capital por mais de dois séculos.","tipo":"numero","n":214,"conta":"1763 − 1549 = ?"},{"m":13,"missao":"PRÓXIMA CENTAURI","materia":"HISTÓRIA","aula":"A linha do tempo","p":"Os portugueses chegaram ao Brasil em 1500. Esse ano fica em qual século?","dica":"Cuidado com o ano que termina em 00. O século XV vai de 1401 até 1500, e o XVI só começa em 1501.","porque":"1500 é o último ano do século XV. Quando o ano termina em 00, não se soma 1: 15, século XV.","tipo":"opcoes","o":["século XVI","século XIV","século XV"],"a":2},{"m":13,"missao":"PRÓXIMA CENTAURI","materia":"ASTRONOMIA","aula":"A estrela vizinha","p":"Um ano-luz é:","dica":"A palavra \"ano\" engana. Pense no que a luz faz durante esse ano inteiro: ela anda.","porque":"Ano-luz é distância: o quanto a luz anda em 1 ano, uns 9,5 trilhões de km.","tipo":"opcoes","o":["um ano muito iluminado","o tempo que a Lua leva para dar uma volta","a distância que a luz anda em um ano","um tipo de estrela"],"a":2},{"m":13,"missao":"PRÓXIMA CENTAURI","materia":"ASTRONOMIA","aula":"A estrela vizinha","p":"Próxima Centauri é uma anã-vermelha. Isso quer dizer que ela é:","dica":"\"Anã\" quer dizer pequena. E a cor vermelha, nas estrelas, mostra que ela é mais fria.","porque":"Anã-vermelha é uma estrela pequena, fria e fraca, tanto que só aparece no telescópio.","tipo":"opcoes","o":["maior e mais quente que o Sol","menor e mais fria que o Sol","um planeta vermelho","um buraco negro"],"a":1},{"m":13,"missao":"PRÓXIMA CENTAURI","materia":"ASTRONOMIA","aula":"A estrela vizinha","p":"A luz de Próxima Centauri leva uns 4 anos para chegar aqui. Uma nave com a METADE da velocidade da luz levaria quantos anos?","dica":"Mais devagar, mais tempo. Metade da velocidade, o dobro do tempo.","porque":"4 × 2 = 8 anos. Andando na metade da velocidade, a viagem demora o dobro.","tipo":"numero","n":8,"conta":"4 × 2 = ?"},{"m":13,"missao":"PRÓXIMA CENTAURI","materia":"ASTRONOMIA","aula":"A estrela vizinha","p":"A Voyager 1 levaria uns 75 mil anos para chegar à Próxima. Quantos séculos são? (1 século = 100 anos)","dica":"Dividir por 100 é cortar dois zeros do fim.","porque":"75.000 ÷ 100 = 750 séculos. Toda a história do Brasil desde 1500 tem só uns 5 séculos!","tipo":"numero","n":750,"conta":"75.000 ÷ 100 = ?"},{"m":13,"missao":"PRÓXIMA CENTAURI","materia":"ASTRONOMIA","aula":"A estrela vizinha","p":"A luz de Próxima Centauri leva uns 4 anos para chegar aqui. Se cadete olhar para ela num telescópio em 2026, vai ver a luz que saiu de lá em que ano?","dica":"A luz que chega hoje saiu de lá alguns anos atrás. Volte 4 anos a partir de 2026.","porque":"2026 − 4 = 2022. A gente vê a estrela como ela era quando a luz saiu de lá.","tipo":"numero","n":2022,"conta":"2026 − 4 = ?"},{"m":13,"missao":"PRÓXIMA CENTAURI","materia":"GEOGRAFIA · AUSTRÁLIA","aula":"O céu do Sul","p":"Qual é a capital da Austrália?","dica":"Não é a maior cidade. É uma cidade planejada para ser a capital, como Brasília.","porque":"Canberra. Sydney é a maior cidade, mas não é a capital.","tipo":"opcoes","o":["Sydney","Canberra","Melbourne","Uluru"],"a":1},{"m":13,"missao":"PRÓXIMA CENTAURI","materia":"GEOGRAFIA · AUSTRÁLIA","aula":"O céu do Sul","p":"Que constelação aparece na bandeira da Austrália e também na do Brasil?","dica":"É uma constelação em forma de cruz, que só se vê bem no céu do Sul.","porque":"O Cruzeiro do Sul, a constelação mais famosa do hemisfério Sul.","tipo":"opcoes","o":["Órion","Escorpião","Ursa Maior","Cruzeiro do Sul"],"a":3},{"m":13,"missao":"PRÓXIMA CENTAURI","materia":"GEOGRAFIA · AUSTRÁLIA","aula":"O céu do Sul","p":"O \"Emu no Céu\" dos povos aborígenes é formado:","dica":"Ele é diferente das constelações que a gente conhece. Ele não liga estrelas: usa o escuro entre elas.","porque":"O emu é desenhado pelas manchas escuras de poeira da Via Láctea, entre as estrelas.","tipo":"opcoes","o":["por estrelas amarelas","por nuvens de chuva","pelas manchas escuras da Via Láctea","pela Lua"],"a":2},{"m":13,"missao":"PRÓXIMA CENTAURI","materia":"GEOGRAFIA · AUSTRÁLIA","aula":"O céu do Sul","p":"Em dezembro é verão no Brasil. E na Austrália, em dezembro, é:","dica":"Os dois países ficam no mesmo hemisfério, o Sul.","porque":"Brasil e Austrália ficam no hemisfério Sul, então as estações são as mesmas na mesma época.","tipo":"opcoes","o":["verão também","inverno","outono"],"a":0},{"m":13,"missao":"PRÓXIMA CENTAURI","materia":"GEOGRAFIA · AUSTRÁLIA","aula":"O céu do Sul","p":"O Brasil tem uns 8,5 milhões de km², e a Austrália, uns 7,7 milhões de km². Quantos MIL km² o Brasil tem a mais?","dica":"Escreva em milhares: 8,5 milhões são 8.500 mil, e 7,7 milhões são 7.700 mil. Agora tire um do outro.","porque":"8.500 − 7.700 = 800. O Brasil tem uns 800 mil km² a mais: os dois são gigantes, mas o Brasil é maior.","tipo":"numero","n":800,"conta":"8.500 mil − 7.700 mil = ? mil"},{"m":14,"missao":"ÓRION","materia":"MATEMÁTICA","aula":"Teorema de Pitágoras","p":"Num triângulo retângulo, como se chama o lado maior, o que fica na frente do canto reto?","dica":"Na escada encostada na parede, é a própria escada. Os outros dois, parede e chão, são os catetos.","porque":"Hipotenusa é o lado maior, o que fica na frente do ângulo reto. Os outros dois são os catetos.","tipo":"opcoes","o":["cateto","hipotenusa","diâmetro","raio"],"a":1},{"m":14,"missao":"ÓRION","materia":"MATEMÁTICA","aula":"Teorema de Pitágoras","p":"Os catetos de um triângulo retângulo medem 3 cm e 4 cm. Quanto mede a hipotenusa, em cm?","dica":"3 × 3 = 9 e 4 × 4 = 16. Some os dois. Que número vezes ele mesmo dá esse total?","porque":"9 + 16 = 25, e 5 × 5 = 25. A hipotenusa mede 5 cm: a terna 3-4-5.","tipo":"numero","n":5,"conta":"3² + 4² = c²"},{"m":14,"missao":"ÓRION","materia":"MATEMÁTICA","aula":"Teorema de Pitágoras","p":"Um triângulo retângulo tem catetos de 6 m e 8 m. Quanto mede a hipotenusa, em metros?","dica":"6 × 6 = 36 e 8 × 8 = 64. Some e ache o número que, vezes ele mesmo, dá o total.","porque":"36 + 64 = 100, e 10 × 10 = 100. Hipotenusa de 10 m: é a terna 3-4-5 em dobro, 6-8-10.","tipo":"numero","n":10,"conta":"6² + 8² = c²"},{"m":14,"missao":"ÓRION","materia":"MATEMÁTICA","aula":"Teorema de Pitágoras","p":"A linha da pipa do Tomás tem 13 m, bem esticada. A pipa está bem acima de um ponto do chão que fica a 5 m do Tomás. A que altura está a pipa, em metros?","dica":"A linha é a hipotenusa e os 5 m são um cateto. 13 × 13 = 169 e 5 × 5 = 25. Tire um do outro e ache o número que, vezes ele mesmo, dá o resultado.","porque":"169 − 25 = 144, e 12 × 12 = 144. A pipa está a 12 m de altura: a terna 5-12-13.","tipo":"numero","n":12,"conta":"13² − 5² = ?²"},{"m":14,"missao":"ÓRION","materia":"MATEMÁTICA","aula":"Teorema de Pitágoras","p":"O pedreiro quer saber se o canto da parede está reto. A partir do canto, ele marca 30 cm numa parede e 40 cm na outra. Se o canto estiver certinho, quantos cm deve dar a distância entre as duas marcas?","dica":"30 e 40 são o 3 e o 4 com um zero a mais: lembre da terna 3-4-5. Ou faça 900 + 1.600 e ache a raiz quadrada.","porque":"900 + 1.600 = 2.500, e 50 × 50 = 2.500. Deu 50 cm? O canto está reto. É a terna 3-4-5 vezes 10.","tipo":"numero","n":50,"conta":"30² + 40² = ?²"},{"m":14,"missao":"ÓRION","materia":"MATEMÁTICA","aula":"Teorema de Pitágoras","p":"O Caio fez 9² + 12² = 81 + 144 = 225 e respondeu que a hipotenusa mede 225. O que faltou?","dica":"225 é a hipotenusa vezes ela mesma, não a hipotenusa. Que número vezes ele mesmo dá 225? Pense na terna 3-4-5 vezes 3.","porque":"225 é o quadrado da hipotenusa. A raiz quadrada de 225 é 15, porque 15 × 15 = 225. É a terna 3-4-5 vezes 3: 9-12-15.","tipo":"opcoes","o":["Nada, a hipotenusa mede 225","Somar 9 + 12: a hipotenusa mede 21","Achar a raiz quadrada de 225: a hipotenusa mede 15","Dividir 225 por 2"],"a":2},{"m":14,"missao":"ÓRION","materia":"ASTRONOMIA","aula":"O berçário de estrelas","p":"As Três Marias fazem parte de qual constelação?","dica":"Elas são três estrelas em fila, no cinturão de um caçador.","porque":"As Três Marias são o cinturão de Órion, o caçador.","tipo":"opcoes","o":["Cruzeiro do Sul","Escorpião","Órion","Ursa Maior"],"a":2},{"m":14,"missao":"ÓRION","materia":"ASTRONOMIA","aula":"O berçário de estrelas","p":"Uma nebulosa como a de Órion é:","dica":"Lembre do apelido dela: berçário de estrelas.","porque":"Estrelas nascem de nuvens de gás e poeira, quando a gravidade junta tudo numa bola quente.","tipo":"opcoes","o":["um planeta gigante","uma nuvem de gás e poeira onde estrelas nascem","um buraco negro"],"a":1},{"m":14,"missao":"ÓRION","materia":"ASTRONOMIA","aula":"O berçário de estrelas","p":"Olhando do Brasil, onde fica a manchinha da Nebulosa de Órion?","dica":"Daqui do hemisfério Sul, Órion aparece de cabeça para baixo.","porque":"No céu do Brasil, Órion fica de cabeça para baixo, e a espadinha com a nebulosa aparece logo acima das Três Marias.","tipo":"opcoes","o":["logo acima das Três Marias","logo abaixo das Três Marias","em volta da Lua"],"a":0},{"m":14,"missao":"ÓRION","materia":"ASTRONOMIA","aula":"O berçário de estrelas","p":"A Nebulosa de Órion fica a uns 1.340 anos-luz. Próxima Centauri, a estrela vizinha, fica a uns 4 (arredondando). A nebulosa fica quantas vezes mais longe?","dica":"Divida por partes: 1.200 ÷ 4 = 300 e 140 ÷ 4 = 35. Depois some.","porque":"1.340 ÷ 4 = 335. A nebulosa fica umas 335 vezes mais longe que a estrela vizinha.","tipo":"numero","n":335,"conta":"1.340 ÷ 4 = ?"},{"m":14,"missao":"ÓRION","materia":"ASTRONOMIA","aula":"O berçário de estrelas","p":"A luz da nebulosa leva uns 1.340 anos para chegar aqui. Se você olhar para ela em 2026, está vendo a luz que saiu de lá em que ano?","dica":"A luz saiu de lá 1.340 anos antes de chegar. Faça 2026 − 1340.","porque":"2026 − 1340 = 686. A luz que você vê hoje saiu de lá por volta do ano 686, no século VII!","tipo":"numero","n":686,"conta":"2026 − 1340 = ?"},{"m":14,"missao":"ÓRION","materia":"HISTÓRIA · MÉXICO","aula":"Os astrônomos maias","p":"Que língua se fala no México?","dica":"É a mesma língua da Argentina e da Espanha. Lembre do \"¡Buenas noches!\" do Don Mateo.","porque":"No México se fala espanhol, a língua que os colonizadores espanhóis levaram para lá.","tipo":"opcoes","o":["inglês","português","francês","espanhol"],"a":3},{"m":14,"missao":"ÓRION","materia":"HISTÓRIA · MÉXICO","aula":"Os astrônomos maias","p":"No equinócio, a sombra na escada da pirâmide de Kukulcán parece:","dica":"Kukulcán, o nome da pirâmide, é o deus serpente emplumada dos maias.","porque":"A sombra forma uma serpente que desce a escada: é Kukulcán, a serpente emplumada.","tipo":"opcoes","o":["um pássaro voando","uma serpente descendo","um sol nascendo"],"a":1},{"m":14,"missao":"ÓRION","materia":"HISTÓRIA · MÉXICO","aula":"Os astrônomos maias","p":"A pirâmide de Kukulcán tem 4 escadas de 91 degraus, mais 1 degrau no topo. Quantos degraus no total?","dica":"Primeiro 91 × 4. Depois some o degrau do topo.","porque":"91 × 4 = 364, e 364 + 1 = 365: um degrau para cada dia do ano!","tipo":"numero","n":365,"conta":"91 × 4 + 1 = ?"},{"m":14,"missao":"ÓRION","materia":"HISTÓRIA · MÉXICO","aula":"Os astrônomos maias","p":"O calendário sagrado maia tinha 13 números combinados com 20 nomes de dias. Quantos dias tinha esse calendário?","dica":"Faça 13 × 2 e ponha um zero no fim.","porque":"13 × 20 = 260 dias.","tipo":"numero","n":260,"conta":"13 × 20 = ?"},{"m":14,"missao":"ÓRION","materia":"HISTÓRIA · MÉXICO","aula":"Os astrônomos maias","p":"Um número maia tem 3 na casa do 20 e a concha do zero nas unidades. Quanto ele vale no nosso jeito de contar?","dica":"A casa de cima vale 20. São 3 grupos de 20, e nada solto nas unidades.","porque":"3 × 20 + 0 = 60. Sem a concha do zero, ninguém saberia se o número era 3 ou 60.","tipo":"numero","n":60,"conta":"3 × 20 + 0 = ?"},{"m":15,"missao":"SAGITÁRIO A*","materia":"INGLÊS","aula":"Bigger and the biggest","p":"Complete: \"Jupiter is ___ than Earth.\" (Júpiter é maior que a Terra.)","dica":"Estamos comparando DUAS coisas, e a frase tem \"than\". Lembre que big dobra o g.","porque":"Comparando dois: bigger than. Júpiter é bem maior que a Terra.","tipo":"opcoes","o":["big","biggest","bigger"],"a":2},{"m":15,"missao":"SAGITÁRIO A*","materia":"INGLÊS","aula":"Bigger and the biggest","p":"\"The smallest planet\" quer dizer:","dica":"Repare no \"the\" antes e no \"-est\" no fim: é o mais de todos.","porque":"The smallest = o menor de todos. No Sistema Solar, é Mercúrio.","tipo":"opcoes","o":["um planeta pequeno","o menor planeta","um planeta maior"],"a":1},{"m":15,"missao":"SAGITÁRIO A*","materia":"INGLÊS","aula":"Bigger and the biggest","p":"Qual é o superlativo de \"hot\" (quente)?","dica":"Hot é curta e termina em vogal + consoante (o + t). Então o t dobra antes do -est.","porque":"The hottest: o mais quente, com t dobrado. Hotter é o comparativo (mais quente que).","tipo":"opcoes","o":["the hottest","the hotest","hotter","the most hot"],"a":0},{"m":15,"missao":"SAGITÁRIO A*","materia":"INGLÊS","aula":"Bigger and the biggest","p":"Complete: \"A black hole is ___ than a comet.\" (Um buraco negro é mais perigoso que um cometa.)","dica":"\"Dangerous\" é uma palavra longa. E a frase compara duas coisas, com \"than\".","porque":"Palavra longa usa more: more dangerous than, mais perigoso que.","tipo":"opcoes","o":["dangerouser","more dangerous","the most dangerous"],"a":1},{"m":15,"missao":"SAGITÁRIO A*","materia":"INGLÊS","aula":"Bigger and the biggest","p":"Qual destas frases está CERTA?","dica":"Confira cada uma: palavra curta usa -er e -est; good muda para better; e \"o mais de todos\" pede the + -est.","porque":"\"Earth is smaller than Jupiter\" está certa. O certo nas outras seria the smallest, better e the biggest (e o maior planeta é Júpiter, não Saturno).","tipo":"opcoes","o":["Mercury is the most small planet.","The Sun is gooder than a candle.","Earth is smaller than Jupiter.","Saturn is the bigger planet of all."],"a":2},{"m":15,"missao":"SAGITÁRIO A*","materia":"INGLÊS","aula":"Bigger and the biggest","p":"Traduza: \"Mauna Kea has some of the best telescopes in the world.\"","dica":"\"The best\" é o superlativo de good: o melhor, os melhores. \"Some of\" quer dizer \"alguns dos\".","porque":"The best = os melhores. A frase diz que o Mauna Kea tem alguns dos melhores telescópios do mundo, e é verdade.","tipo":"opcoes","o":["O Mauna Kea tem telescópios melhores que o mundo.","O Mauna Kea tem alguns telescópios bons.","O Mauna Kea tem os piores telescópios do mundo.","O Mauna Kea tem alguns dos melhores telescópios do mundo."],"a":3},{"m":15,"missao":"SAGITÁRIO A*","materia":"ASTRONOMIA","aula":"O buraco negro do centro","p":"Um buraco negro é:","dica":"Pense no porquê de ele ser \"negro\", escuro: a luz não consegue sair.","porque":"A gravidade é tão forte que nem a luz escapa. Sem luz saindo, ele fica escuro.","tipo":"opcoes","o":["um buraco no chão do espaço","uma estrela muito brilhante","um planeta preto","um lugar com gravidade tão forte que nem a luz escapa"],"a":3},{"m":15,"missao":"SAGITÁRIO A*","materia":"ASTRONOMIA","aula":"O buraco negro do centro","p":"A borda de onde nada consegue voltar se chama:","dica":"É um \"horizonte\": uma linha que separa o que dá para ver do que não dá.","porque":"Horizonte de eventos. Em Sagitário A*, ele fica a uns 12 milhões de km do centro.","tipo":"opcoes","o":["anel de Saturno","horizonte de eventos","linha do Equador"],"a":1},{"m":15,"missao":"SAGITÁRIO A*","materia":"ASTRONOMIA","aula":"O buraco negro do centro","p":"Sagitário A* tem a massa de 4 milhões de Sóis. Escreva esse número só com algarismos:","dica":"Um milhão é 1 seguido de seis zeros. Então 4 milhões é 4 e mais seis zeros.","porque":"4.000.000: quatro milhões de Sóis num lugar só.","tipo":"numero","n":4000000,"conta":null},{"m":15,"missao":"SAGITÁRIO A*","materia":"ASTRONOMIA","aula":"O buraco negro do centro","p":"Na missão, o Relógio de Dobra vai mostrar que 1 hora perto do buraco negro valeu 3 dias na Terra. Quantas HORAS passaram na Terra?","dica":"Cada dia tem 24 horas. Multiplique por 3.","porque":"3 × 24 = 72 horas na Terra, enquanto na nave passou só 1 hora.","tipo":"numero","n":72,"conta":"3 × 24 = ?"},{"m":15,"missao":"SAGITÁRIO A*","materia":"ASTRONOMIA","aula":"O buraco negro do centro","p":"O Sol leva uns 230 milhões de anos para dar uma volta em torno do centro da galáxia. Ele tem uns 4,6 bilhões de anos, ou seja, 4.600 milhões. Quantas voltas ele já deu, mais ou menos?","dica":"Corte um zero dos dois números: 460 ÷ 23. Pense: 23 × 2 = 46.","porque":"4.600 ÷ 230 = 20 voltas. Em toda a vida do Sol, só umas 20 voltas na galáxia!","tipo":"numero","n":20,"conta":"4.600 ÷ 230 = ?"},{"m":15,"missao":"SAGITÁRIO A*","materia":"GEOGRAFIA · HAVAÍ","aula":"Navegando pelas estrelas","p":"Os navegadores polinésios atravessavam o oceano guiados por:","dica":"Faz centenas de anos: não existia nenhuma máquina. Eles liam a natureza.","porque":"Eles se guiavam pelas estrelas, pelas ondas e pelos pássaros.","tipo":"opcoes","o":["GPS e celular","estrelas, ondas e pássaros","mapas de papel","aviões"],"a":1},{"m":15,"missao":"SAGITÁRIO A*","materia":"GEOGRAFIA · HAVAÍ","aula":"Navegando pelas estrelas","p":"As ilhas do Havaí foram formadas por:","dica":"O Mauna Kea, onde estamos, é um deles.","porque":"Vulcões nasceram no fundo do mar e foram crescendo até sair da água.","tipo":"opcoes","o":["geleiras","terremotos","rios","vulcões"],"a":3},{"m":15,"missao":"SAGITÁRIO A*","materia":"GEOGRAFIA · HAVAÍ","aula":"Navegando pelas estrelas","p":"O Mauna Kea tem 4.207 m acima do mar e uns 6.000 m embaixo d'água. Qual é a altura total, da base até o topo, em metros? (Use os números dados.)","dica":"Some a parte de cima com a parte de baixo: 4.207 + 6.000.","porque":"4.207 + 6.000 = 10.207 m. O Everest tem 8.849 m: o Mauna Kea é mais alto, contando da base!","tipo":"numero","n":10207,"conta":"4.207 + 6.000 = ?"},{"m":15,"missao":"SAGITÁRIO A*","materia":"GEOGRAFIA · HAVAÍ","aula":"Navegando pelas estrelas","p":"Do alto do Mauna Kea, a Estrela Polar aparece a uns 20° acima do horizonte. Então a latitude do Havaí é de cerca de:","dica":"A altura da Estrela Polar, em graus, é a própria latitude. E a Polar só aparece para quem está ao norte do Equador.","porque":"Polar a 20° de altura = latitude de uns 20° norte.","tipo":"opcoes","o":["70° norte","20° sul","20° norte"],"a":2},{"m":15,"missao":"SAGITÁRIO A*","materia":"GEOGRAFIA · HAVAÍ","aula":"Navegando pelas estrelas","p":"O Havaí fica a uns 20° de latitude norte, e cada grau vale uns 111 km. Quantos km, mais ou menos, separam o Havaí da linha do Equador?","dica":"Do Equador (0°) até 20° são 20 graus. Multiplique 20 por 111: faça 2 × 111 e ponha um zero no fim.","porque":"20 × 111 = 2.220 km até o Equador.","tipo":"numero","n":2220,"conta":"20 × 111 = ?"},{"m":16,"missao":"MAGALHÃES","materia":"MATEMÁTICA","aula":"Função afim","p":"O mototáxi do Capão cobra y = 2·x + 4, com x em km e y em reais. Quanto custa uma corrida de 5 km, em reais?","dica":"Troque o x por 5: primeiro 2 × 5, depois some 4.","porque":"2 × 5 = 10, e 10 + 4 = 14. A corrida custa R$ 14.","tipo":"numero","n":14,"conta":"y = 2 × 5 + 4"},{"m":16,"missao":"MAGALHÃES","materia":"MATEMÁTICA","aula":"Função afim","p":"Na lei y = 3·x + 7, quem é o a e quem é o b?","dica":"O a é o número que multiplica o x. O b é o número que fica sozinho.","porque":"a = 3, porque multiplica o x. b = 7, o número sozinho: o valor de y quando x = 0.","tipo":"opcoes","o":["a = 3 e b = 7","a = 7 e b = 3","a = 3 e b = 10"],"a":0},{"m":16,"missao":"MAGALHÃES","materia":"MATEMÁTICA","aula":"Função afim","p":"O tanque da nave segue y = −5·x + 50: x é o tempo em horas e y são os litros que sobram. Quantos litros sobram depois de 4 horas?","dica":"Em 4 horas a nave gasta 4 × 5 = 20 litros. Tire isso dos 50.","porque":"−5 × 4 = −20, e −20 + 50 = 30 litros.","tipo":"numero","n":30,"conta":"y = −5 × 4 + 50"},{"m":16,"missao":"MAGALHÃES","materia":"MATEMÁTICA","aula":"Função afim","p":"Em qual destas funções a reta do gráfico DESCE?","dica":"Olhe o sinal do a, o número que multiplica o x. A reta desce quando o a é negativo.","porque":"Em y = −2·x + 9, a = −2: a cada 1 que x cresce, y perde 2. A reta desce. Em y = 6, a = 0: a reta fica deitada.","tipo":"opcoes","o":["y = 4·x + 1","y = −2·x + 9","y = 6"],"a":1},{"m":16,"missao":"MAGALHÃES","materia":"MATEMÁTICA","aula":"Função afim","p":"O mototáxi cobra y = 2·x + 4. cadete pagou R$ 20 por uma corrida. Quantos km a corrida teve?","dica":"Primeiro tire os R$ 4 de saída: 20 − 4 = 16. Esses R$ 16 são de km a R$ 2 cada um.","porque":"20 − 4 = 16, e 16 ÷ 2 = 8 km. Confira: 2 × 8 + 4 = 20.","tipo":"numero","n":8,"conta":"2·x + 4 = 20"},{"m":16,"missao":"MAGALHÃES","materia":"MATEMÁTICA","aula":"Função afim","p":"Dois mototáxis: o da Dona Nina cobra y = 2·x + 4 e o do Seu Tião cobra y = 3·x + 1 (x em km). Para uma corrida de 2 km, qual sai mais barato?","dica":"Calcule as duas com x = 2: 2 × 2 + 4 e 3 × 2 + 1. Depois compare.","porque":"Dona Nina: 2 × 2 + 4 = 8. Seu Tião: 3 × 2 + 1 = 7. R$ 7 é mais barato: o do Seu Tião.","tipo":"opcoes","o":["O da Dona Nina","Custam o mesmo","O do Seu Tião"],"a":2},{"m":16,"missao":"MAGALHÃES","materia":"ASTRONOMIA","aula":"As galáxias vizinhas","p":"O que são as Nuvens de Magalhães?","dica":"Elas são feitas de bilhões de estrelas e ficam fora da Via Láctea.","porque":"São duas galáxias-anãs, cheias de estrelas, que giram em volta da Via Láctea.","tipo":"opcoes","o":["Nuvens de chuva muito altas","Duas galáxias pequenas, vizinhas da Via Láctea","Dois cometas"],"a":1},{"m":16,"missao":"MAGALHÃES","materia":"ASTRONOMIA","aula":"As galáxias vizinhas","p":"Em que parte da Terra as Nuvens de Magalhães aparecem melhor no céu?","dica":"Elas ficam perto do polo sul do céu. E o Brasil fica em qual hemisfério?","porque":"Elas ficam perto do polo sul do céu, então aparecem melhor no hemisfério Sul. O Brasil tem sorte!","tipo":"opcoes","o":["No hemisfério Norte","No hemisfério Sul","Só no Polo Norte"],"a":1},{"m":16,"missao":"MAGALHÃES","materia":"ASTRONOMIA","aula":"As galáxias vizinhas","p":"A Grande Nuvem fica a 160 mil anos-luz e a Pequena, a 200 mil. Quantos anos-luz a Pequena fica mais longe que a Grande?","dica":"Faça 200 − 160 = 40 e depois ponha os três zeros do \"mil\".","porque":"200.000 − 160.000 = 40.000 anos-luz.","tipo":"numero","n":40000,"conta":"200.000 − 160.000 = ?"},{"m":16,"missao":"MAGALHÃES","materia":"ASTRONOMIA","aula":"As galáxias vizinhas","p":"Por que as Nuvens de Magalhães parecem manchas de nuvem, e não pontinhos de estrela?","dica":"Pense na Via Láctea: de longe, as estrelas dela também viram uma faixa de luz.","porque":"Cada Nuvem tem bilhões de estrelas. Elas estão tão longe que o olho não separa uma da outra: vê só uma mancha clara.","tipo":"opcoes","o":["Porque são bilhões de estrelas tão longe que a luz delas se mistura","Porque são feitas de vapor d'água","Porque estão dentro da atmosfera da Terra"],"a":0},{"m":16,"missao":"MAGALHÃES","materia":"ASTRONOMIA","aula":"As galáxias vizinhas","p":"A supernova da Grande Nuvem foi vista em 1987. A luz dela viajou uns 160 mil anos até a Terra. Quando a estrela explodiu de verdade?","dica":"A luz demora para viajar. A gente só vê a explosão quando a luz dela chega aqui.","porque":"A luz levou uns 160 mil anos no caminho. Então a estrela explodiu uns 160 mil anos antes de 1987: olhar para o céu é olhar para o passado.","tipo":"opcoes","o":["Em 1987, no mesmo dia em que foi vista","Uns 1.987 anos atrás","Uns 160 mil anos antes de 1987"],"a":2},{"m":16,"missao":"MAGALHÃES","materia":"HISTÓRIA · PORTUGAL","aula":"As Grandes Navegações","p":"Qual é a capital de Portugal?","dica":"É a cidade na beira do rio Tejo, onde a capitã Inês está agora.","porque":"Lisboa é a capital de Portugal. Madri é a capital da Espanha.","tipo":"opcoes","o":["Porto","Madri","Lisboa","Belém"],"a":2},{"m":16,"missao":"MAGALHÃES","materia":"HISTÓRIA · PORTUGAL","aula":"As Grandes Navegações","p":"Como se chamavam os barcos leves das Grandes Navegações?","dica":"O nome está no slide: barcos leves com velas grandes.","porque":"Caravelas: barcos leves e rápidos, com velas grandes, que aguentavam o mar aberto.","tipo":"opcoes","o":["Caravelas","Canoas","Submarinos","Balsas"],"a":0},{"m":16,"missao":"MAGALHÃES","materia":"HISTÓRIA · PORTUGAL","aula":"As Grandes Navegações","p":"Para que servia o astrolábio?","dica":"Em alto-mar não há placas. Os navegadores olhavam para o céu.","porque":"O astrolábio mede o ângulo do Sol ou de uma estrela acima do horizonte. Com ele, dava para saber o quanto o navio estava ao norte ou ao sul.","tipo":"opcoes","o":["Para pescar em alto-mar","Para medir o ângulo do Sol e das estrelas e saber onde o navio estava","Para medir a velocidade do vento"],"a":1},{"m":16,"missao":"MAGALHÃES","materia":"HISTÓRIA · PORTUGAL","aula":"As Grandes Navegações","p":"Quando a frota de Cabral chegou em 1500, quem já vivia na terra que hoje é o Brasil?","dica":"Os portugueses chegaram, mas não foram os primeiros a morar aqui.","porque":"Milhões de indígenas, de muitos povos diferentes, já viviam aqui havia milhares de anos. Por isso muitos historiadores preferem dizer \"chegada\" e não \"descobrimento\".","tipo":"opcoes","o":["Ninguém: a terra estava vazia","Só animais","Muitos povos indígenas, havia milhares de anos"],"a":2},{"m":16,"missao":"MAGALHÃES","materia":"HISTÓRIA · PORTUGAL","aula":"As Grandes Navegações","p":"A frota de Cabral saiu de Lisboa em 9 de março de 1500 e chegou à Bahia em 22 de abril. Quantos dias durou a viagem? (Março tem 31 dias.)","dica":"Primeiro conte os dias que faltavam em março depois do dia 9: 31 − 9. Depois some os 22 dias de abril.","porque":"De 9 a 31 de março são 31 − 9 = 22 dias. Mais 22 dias de abril: 22 + 22 = 44 dias de viagem.","tipo":"numero","n":44,"conta":"(31 − 9) + 22 = ?"},{"m":17,"missao":"ANDRÔMEDA","materia":"PORTUGUÊS","aula":"Figuras de linguagem","p":"\"A Lua é como uma lanterna no céu.\" Que figura de linguagem é essa?","dica":"Procure uma palavra de ligação, como \"como\" ou \"parece\".","porque":"Tem a palavra \"como\" ligando a Lua e a lanterna: é uma comparação.","tipo":"opcoes","o":["Metáfora","Comparação","Hipérbole"],"a":1},{"m":17,"missao":"ANDRÔMEDA","materia":"PORTUGUÊS","aula":"Figuras de linguagem","p":"\"A Via Láctea é um rio de luz.\" Que figura de linguagem é essa?","dica":"A frase diz que a Via Láctea É um rio, sem usar \"como\".","porque":"Diz direto que uma coisa é a outra, sem \"como\": é uma metáfora.","tipo":"opcoes","o":["Comparação","Personificação","Metáfora"],"a":2},{"m":17,"missao":"ANDRÔMEDA","materia":"PORTUGUÊS","aula":"Figuras de linguagem","p":"\"As estrelas piscavam para o Kdok.\" Que figura de linguagem é essa?","dica":"Estrela pisca para alguém como gente faz? Quem pisca de propósito para os outros?","porque":"Piscar para alguém é coisa de gente. A frase dá uma ação humana às estrelas: é personificação.","tipo":"opcoes","o":["Personificação","Hipérbole","Comparação"],"a":0},{"m":17,"missao":"ANDRÔMEDA","materia":"PORTUGUÊS","aula":"Figuras de linguagem","p":"\"Esperei mil anos por esse lançamento!\" Que figura de linguagem é essa?","dica":"Alguém espera mil anos de verdade? A frase está exagerando?","porque":"Ninguém espera mil anos: é um exagero de propósito, para mostrar que a espera pareceu longa. É hipérbole.","tipo":"opcoes","o":["Comparação","Hipérbole","Metáfora"],"a":1},{"m":17,"missao":"ANDRÔMEDA","materia":"PORTUGUÊS","aula":"Figuras de linguagem","p":"Qual destas frases tem PERSONIFICAÇÃO?","dica":"Procure algo que não é gente, mas sente ou age como gente.","porque":"Ficar tímida e se esconder é coisa de gente: a Lua ganhou sentimento humano. As outras são metáfora, comparação e hipérbole.","tipo":"opcoes","o":["A nave é uma flecha de prata.","O foguete parece um lápis gigante.","A Lua, tímida, se escondeu atrás da serra.","Comi umas cem pizzas no jantar."],"a":2},{"m":17,"missao":"ANDRÔMEDA","materia":"PORTUGUÊS","aula":"Figuras de linguagem","p":"Na frase \"Seus olhos são duas estrelas\", o que a metáfora quer dizer?","dica":"A metáfora pega uma qualidade da estrela e passa para os olhos. Qual qualidade da estrela é a mais conhecida?","porque":"A metáfora usa o brilho das estrelas para dizer que os olhos brilham e são bonitos. Ela não fala do gás nem da distância.","tipo":"opcoes","o":["Que os olhos são feitos de gás quente","Que os olhos brilham e são bonitos","Que os olhos ficam muito longe"],"a":1},{"m":17,"missao":"ANDRÔMEDA","materia":"ASTRONOMIA","aula":"A galáxia vizinha","p":"O que é Andrômeda?","dica":"Ela tem cerca de 1 trilhão de estrelas. Uma coisa com tantas estrelas é o quê?","porque":"Andrômeda é uma galáxia, com cerca de 1 trilhão de estrelas: a nossa grande vizinha.","tipo":"opcoes","o":["Uma estrela muito brilhante","Um planeta do Sistema Solar","A grande galáxia mais próxima da nossa"],"a":2},{"m":17,"missao":"ANDRÔMEDA","materia":"ASTRONOMIA","aula":"A galáxia vizinha","p":"Numa noite bem escura, como Andrômeda aparece a olho nu?","dica":"Al-Sufi a chamou de \"pequena nuvem\". Por quê?","porque":"Ela aparece como uma mancha fraca, parecida com uma nuvenzinha. Por isso Al-Sufi a chamou de \"pequena nuvem\".","tipo":"opcoes","o":["Como uma mancha fraquinha","Como uma bola grande e colorida","Não dá para ver sem telescópio"],"a":0},{"m":17,"missao":"ANDRÔMEDA","materia":"ASTRONOMIA","aula":"A galáxia vizinha","p":"O que os astrônomos descobriram sobre Andrômeda nos anos 1920?","dica":"Medindo a distância, viram que ela fica fora da Via Láctea.","porque":"Hubble mediu a distância e mostrou que Andrômeda fica muito fora da Via Láctea: é outra galáxia. O universo ficou bem maior.","tipo":"opcoes","o":["Que ela é uma nuvem de gás dentro da Via Láctea","Que ela é outra galáxia, muito longe da nossa","Que ela é uma estrela que explodiu"],"a":1},{"m":17,"missao":"ANDRÔMEDA","materia":"ASTRONOMIA","aula":"A galáxia vizinha","p":"A luz de Andrômeda leva 2,5 milhões de anos para chegar aqui. Quando essa luz saiu de lá, quem vivia na Terra?","dica":"Os dinossauros sumiram há uns 66 milhões de anos. E 2,5 milhões de anos é bem menos que isso.","porque":"Há 2,5 milhões de anos os dinossauros já tinham sumido havia muito tempo, e os humanos de hoje ainda não existiam. Viviam os ancestrais antigos dos humanos, na África.","tipo":"opcoes","o":["Pessoas com celular","Os ancestrais bem antigos dos humanos","Os dinossauros"],"a":1},{"m":17,"missao":"ANDRÔMEDA","materia":"ASTRONOMIA","aula":"A galáxia vizinha","p":"Quando Andrômeda e a Via Láctea se juntarem, o que deve acontecer com as estrelas?","dica":"Pense na distância entre as estrelas. A mais perto do Sol fica a mais de 4 anos-luz dele.","porque":"Entre uma estrela e outra há um espaço vazio enorme. Por isso, quando as galáxias se juntarem, quase nenhuma estrela vai bater: elas só vão mudar de caminho.","tipo":"opcoes","o":["Quase todas vão bater umas nas outras e explodir","Todas vão cair dentro do Sol","Quase nenhuma vai bater, porque há muito espaço vazio entre elas"],"a":2},{"m":17,"missao":"ANDRÔMEDA","materia":"HISTÓRIA · EGITO","aula":"Os observadores do Nilo","p":"Qual é a capital do Egito?","dica":"Gizé é onde ficam as pirâmides, e Nilo é o nome do rio. A capital é outra cidade.","porque":"A capital do Egito é o Cairo. Gizé fica bem pertinho dela.","tipo":"opcoes","o":["Gizé","Cairo","Alexandria","Nilo"],"a":1},{"m":17,"missao":"ANDRÔMEDA","materia":"HISTÓRIA · EGITO","aula":"Os observadores do Nilo","p":"Como se chama a escrita com desenhos dos antigos egípcios?","dica":"O nome está no slide das pirâmides.","porque":"Hieróglifos: cada desenho podia ser uma ideia ou um som.","tipo":"opcoes","o":["Algarismos romanos","Alfabeto","Hieróglifos"],"a":2},{"m":17,"missao":"ANDRÔMEDA","materia":"HISTÓRIA · EGITO","aula":"Os observadores do Nilo","p":"As pirâmides têm uns 4.500 anos. Quantos séculos é isso?","dica":"1 século = 100 anos. Dividir por 100 é cortar dois zeros.","porque":"4.500 ÷ 100 = 45 séculos.","tipo":"numero","n":45,"conta":"4.500 ÷ 100 = ?"},{"m":17,"missao":"ANDRÔMEDA","materia":"HISTÓRIA · EGITO","aula":"Os observadores do Nilo","p":"O que avisava os egípcios de que as cheias do rio Nilo estavam chegando?","dica":"Eles marcavam o ano novo olhando para uma estrela muito brilhante.","porque":"Quando Sírius voltava a aparecer de madrugada, antes do Sol, a cheia do Nilo estava perto. O céu e o rio marcavam o ano.","tipo":"opcoes","o":["A estrela Sírius voltando a aparecer antes do nascer do Sol","A Lua cheia","Os camelos ficando agitados"],"a":0},{"m":17,"missao":"ANDRÔMEDA","materia":"HISTÓRIA · EGITO","aula":"Os observadores do Nilo","p":"O calendário egípcio tinha 12 meses de 30 dias, mais alguns dias de festa no fim, para completar 365 dias. Quantos dias de festa?","dica":"Primeiro veja quantos dias têm os 12 meses: 12 × 30. Depois veja quanto falta para 365.","porque":"12 × 30 = 360 dias. 365 − 360 = 5 dias de festa.","tipo":"numero","n":5,"conta":"365 − 12 × 30 = ?"},{"m":18,"missao":"A BORDA","materia":"PROVA FINAL","aula":"Um pouco de tudo","p":"A viagem até a borda do universo tem 50 etapas, e cadete já fez 3/5 delas. Quantas etapas já foram?","dica":"Primeiro 1/5 de 50: divida 50 por 5. Depois multiplique por 3.","porque":"50 ÷ 5 = 10, e 10 × 3 = 30 etapas.","tipo":"numero","n":30,"conta":"3/5 de 50 = ?"},{"m":18,"missao":"A BORDA","materia":"PROVA FINAL","aula":"Um pouco de tudo","p":"Na frase \"A nave azul pousou devagar.\", qual palavra é um ADJETIVO?","dica":"O adjetivo dá uma característica ao substantivo: ele diz como a coisa é.","porque":"\"Azul\" diz como é a nave: é adjetivo. \"Nave\" é substantivo, \"pousou\" é verbo e \"devagar\" é advérbio (diz como ela pousou).","tipo":"opcoes","o":["nave","azul","pousou","devagar"],"a":1},{"m":18,"missao":"A BORDA","materia":"PROVA FINAL","aula":"Um pouco de tudo","p":"O Vale do Capão fica a uns 12° ao sul da linha do Equador. Em que hemisfério ele está?","dica":"A linha do Equador divide a Terra em duas metades. \"Ao sul do Equador\" fica em qual metade?","porque":"Quem fica ao sul do Equador está no hemisfério Sul. A latitude do Capão é de uns 12° Sul.","tipo":"opcoes","o":["No hemisfério Norte","No hemisfério Sul","Exatamente em cima do Equador"],"a":1},{"m":18,"missao":"A BORDA","materia":"PROVA FINAL","aula":"Um pouco de tudo","p":"Uma luneta custava R$ 80 e teve 25% de desconto. Por quanto ela ficou, em reais?","dica":"25% é a quarta parte: 80 ÷ 4 é o desconto. Depois tire o desconto do preço.","porque":"80 ÷ 4 = 20 reais de desconto. 80 − 20 = 60 reais.","tipo":"numero","n":60,"conta":"80 − 25% de 80 = ?"},{"m":18,"missao":"A BORDA","materia":"PROVA FINAL","aula":"Um pouco de tudo","p":"Complete: \"Jupiter is ___ than Earth.\"","dica":"Comparando duas coisas com \"than\", o adjetivo curto ganha -er no fim.","porque":"Comparando dois planetas, usa-se \"bigger than\": \"Júpiter é maior que a Terra\". O big dobra o g: bigger.","tipo":"opcoes","o":["big","the biggest","bigger"],"a":2},{"m":18,"missao":"A BORDA","materia":"PROVA FINAL","aula":"Um pouco de tudo","p":"Quando o gelo derrete e vira água líquida, como se chama essa mudança de estado?","dica":"É a passagem do estado sólido para o estado líquido.","porque":"Do sólido para o líquido é fusão. Do líquido para o gasoso é vaporização; do gasoso para o líquido, condensação; do líquido para o sólido, solidificação.","tipo":"opcoes","o":["Evaporação","Fusão","Condensação","Solidificação"],"a":1},{"m":18,"missao":"A BORDA","materia":"PROVA FINAL","aula":"Um pouco de tudo","p":"O Kdok pensou num número, multiplicou por 3 e somou 7. Deu 25. Resolva a equação e descubra o número.","dica":"Tire 7 dos dois lados: 3x = 18. Depois divida os dois lados por 3.","porque":"3x = 25 − 7 = 18, e x = 18 ÷ 3 = 6. Conferindo: 3 × 6 + 7 = 25.","tipo":"numero","n":6,"conta":"3x + 7 = 25"},{"m":18,"missao":"A BORDA","materia":"PROVA FINAL","aula":"Um pouco de tudo","p":"A frota de Cabral chegou à Bahia em 1500. Esse ano pertence a qual século?","dica":"O século XV vai do ano 1401 até o ano 1500. O ano terminado em 00 é o último do seu século.","porque":"O século XV começa em 1401 e termina em 1500. Por isso 1500 ainda é século XV; o século XVI só começa em 1501.","tipo":"opcoes","o":["Século XIV","Século XV","Século XVI"],"a":1},{"m":18,"missao":"A BORDA","materia":"PROVA FINAL","aula":"Um pouco de tudo","p":"Qual destas frases segue a norma-padrão da concordância?","dica":"O verbo concorda com o sujeito. Em \"falta\" ou \"faltam\", o sujeito vem depois do verbo: o que é que falta?","porque":"Quem falta são \"dois minutos\", no plural, então o verbo vai para o plural: faltam. As outras deviam ser: os astronautas chegaram, faltam duas peças, as estrelas brilham.","tipo":"opcoes","o":["Os astronauta chegaram cansados.","Faltam dois minutos para o lançamento.","Falta duas peças na nave.","As estrelas brilha muito."],"a":1},{"m":18,"missao":"A BORDA","materia":"PROVA FINAL","aula":"Um pouco de tudo","p":"Uma rampa de lançamento sobe 5 m de altura e avança 12 m no chão. Quanto mede a rampa (a hipotenusa), em metros?","dica":"5 × 5 = 25 e 12 × 12 = 144. Some os dois e procure o número que, vezes ele mesmo, dá essa soma.","porque":"25 + 144 = 169, e 13 × 13 = 169. A rampa mede 13 m.","tipo":"numero","n":13,"conta":"5² + 12² = c²"},{"m":18,"missao":"A BORDA","materia":"ASTRONOMIA","aula":"A história do universo","p":"Quantos anos tem o universo, mais ou menos?","dica":"Cuidado: 4,6 bilhões de anos é a idade do Sol, e o universo é bem mais velho que ele.","porque":"O universo tem uns 13,8 bilhões de anos. O Sol, uns 4,6 bilhões: ele nasceu bem depois.","tipo":"opcoes","o":["2.026 anos","4,6 bilhões de anos","13,8 bilhões de anos","1 milhão de anos"],"a":2},{"m":18,"missao":"A BORDA","materia":"ASTRONOMIA","aula":"A história do universo","p":"A luz mais antiga do universo foi descoberta sem querer, em 1964. Com qual aparelho?","dica":"Os cientistas ouviam um chiado que não parava.","porque":"Foi com uma antena gigante. O chiado que os cientistas ouviam era a luz mais antiga do universo.","tipo":"opcoes","o":["Uma antena","Um microscópio","Uma luneta de brinquedo"],"a":0},{"m":18,"missao":"A BORDA","materia":"ASTRONOMIA","aula":"A história do universo","p":"Por que se diz universo OBSERVÁVEL?","dica":"A luz demora para viajar, e o universo tem uma idade.","porque":"Desde o começo do universo, a luz só teve tempo de vir de uma certa distância. O que está além disso ainda não dá para ver.","tipo":"opcoes","o":["Porque tem um observatório na borda dele","Porque só vemos até onde a luz teve tempo de chegar até nós","Porque dá para ver tudo o que existe"],"a":1},{"m":18,"missao":"A BORDA","materia":"ASTRONOMIA","aula":"A história do universo","p":"A luz mais antiga é muito fria: uns −270 °C. A água congela a 0 °C. Quantos graus ela está abaixo do ponto de congelamento da água?","dica":"Na reta numérica, do −270 até o 0 há quantas casas?","porque":"De −270 até 0 são 270 graus. Ela está 270 graus abaixo do congelamento da água.","tipo":"numero","n":270,"conta":"0 − (−270) = ?"},{"m":18,"missao":"A BORDA","materia":"ASTRONOMIA","aula":"A história do universo","p":"O universo tem uns 13,8 bilhões de anos, e o Sol, uns 4,6 bilhões. Quantos MILHÕES de anos o universo já tinha quando o Sol nasceu?","dica":"Passe para milhões: 13,8 bilhões = 13.800 milhões e 4,6 bilhões = 4.600 milhões. Depois subtraia.","porque":"13.800 − 4.600 = 9.200 milhões de anos (9,2 bilhões). O universo já era bem velho quando o Sol nasceu.","tipo":"numero","n":9200,"conta":"13.800 − 4.600 = ?"},{"m":18,"missao":"A BORDA","materia":"CIÊNCIAS · CÉU DO CAPÃO","aula":"O céu de casa","p":"Por que o céu do Capão tem tantas estrelas visíveis?","dica":"Pense no que apaga as estrelas fracas nas cidades grandes.","porque":"Com menos luz artificial, o céu fica mais escuro e as estrelas fracas aparecem.","tipo":"opcoes","o":["Porque o Capão fica mais perto do espaço","Porque tem pouca luz de cidade (pouca poluição luminosa)","Porque as estrelas gostam de lá"],"a":1},{"m":18,"missao":"A BORDA","materia":"CIÊNCIAS · CÉU DO CAPÃO","aula":"O céu de casa","p":"Qual grupo de estrelas aparece na bandeira do Brasil e também no céu do Capão?","dica":"O nome dele já diz de que lado do céu ele fica.","porque":"O Cruzeiro do Sul está na bandeira e brilha no céu do Capão. Ele ajuda a achar o sul.","tipo":"opcoes","o":["Cruzeiro do Sul","Ursa Maior","Cassiopeia"],"a":0},{"m":18,"missao":"A BORDA","materia":"CIÊNCIAS · CÉU DO CAPÃO","aula":"O céu de casa","p":"Quantas estrelas tem a bandeira do Brasil?","dica":"Uma para cada estado (são 26) e mais uma para o Distrito Federal.","porque":"26 estados + 1 Distrito Federal = 27 estrelas.","tipo":"numero","n":27,"conta":"26 + 1 = ?"},{"m":18,"missao":"A BORDA","materia":"CIÊNCIAS · CÉU DO CAPÃO","aula":"O céu de casa","p":"A bandeira do Brasil mostra o céu do Rio na manhã de 15 de novembro de qual ano?","dica":"É o ano da Proclamação da República.","porque":"Em 1889, no dia da Proclamação da República.","tipo":"numero","n":1889,"conta":null},{"m":18,"missao":"A BORDA","materia":"CIÊNCIAS · CÉU DO CAPÃO","aula":"O céu de casa","p":"Marcos Pontes foi ao espaço em 2006. Yuri Gagarin, o primeiro ser humano no espaço, foi em 1961. Quantos anos depois de Gagarin foi o primeiro brasileiro?","dica":"Faça 2006 − 1961. Dica: de 1961 até 2001 são 40 anos.","porque":"De 1961 até 2001 são 40 anos, e de 2001 até 2006, mais 5. 40 + 5 = 45 anos.","tipo":"numero","n":45,"conta":"2006 − 1961 = ?"}];
